window.RECIPE_LOCALES["en"]["primer-a"] = { title: "How-to primer: common preparations & safety basics", html: "<section class=\"entry-section\"><h3>Shared safety basics (read before any recipe)</h3><p>1. <strong>Clean tools.</strong> Wash hands, jars, lids, spoons, and strainers. For alcohol or vinegar extracts, start with dry herbs and dry jars to reduce spoilage risk. 2. <strong>Label everything.</strong> Name, ingredients, date made, alcohol % if applicable, and “external only” when true. Unlabeled jars are how accidents happen. 3. <strong>Know your plant.</strong> Use culinary-grade or correctly identified dried herbs from reputable suppliers. Never forage unless you are trained; look-alikes can be toxic. 4. <strong>Start low.</strong> First use: small amount, watch for allergy (itching, swelling, hives, breathing trouble → emergency care). 5. <strong>Pregnancy, nursing, children.</strong> Many herbs are <strong>not</strong> appropriate. When a recipe does not explicitly say “food-level kitchen spice only,” assume <strong>ask a clinician first</strong>. Honey is <strong>never</strong> for infants under 1 year (botulism risk). 6. <strong>Medicines.</strong> Herbs can interact with drugs. <strong>Never stop prescribed medicines</strong> based on this document—ask a pharmacist or clinician. 7. <strong>Essential oils (EO).</strong> Not the same as dried herbs in tea. <strong>Do not</strong> casually ingest EOs. For topical use, dilute heavily in a carrier oil and patch-test. Keep away from eyes, inner ears, mucous membranes, pets’ cages, and unsupervised children. 8. <strong>When to discard.</strong> Mold, off smells, fizzing that shouldn’t be there, cloudy oil that was clear, or past a sensible shelf window → discard. When unsure, throw it out. 9. <strong>When to see a clinician.</strong> High fever, trouble breathing, chest pain, severe dehydration, bloody stool/vomit, unexplained weight loss, wounds that worsen, suspected poisoning, psychiatric crisis, or any symptom that frightens you. Herbal kitchen craft is <strong>not</strong> urgent care.</p></section><section class=\"entry-section\"><h3>Infusion (tea — delicate parts)</h3><p><strong>What it is:</strong> Hot water poured over leaves, flowers, or soft plant parts; steeped covered.</p><p><strong>Basic method:</strong> Use about <strong>1–2 teaspoons dried herb</strong> (or a small handful of fresh) per <strong>8 oz (240 ml)</strong> near-boiling water. Cover 5–15 minutes. Strain.</p><p><strong>Safety:</strong> Covering keeps aromatic oils in the cup. Do not assume “natural = unlimited.” Discard leftover tea after a day in the fridge, or sooner if it smells off.</p></section><section class=\"entry-section\"><h3>Decoction (simmer — tougher parts)</h3><p><strong>What it is:</strong> Roots, barks, seeds, or woody material simmered in water.</p><p><strong>Basic method:</strong> About <strong>1 teaspoon to 1 tablespoon dried hard material</strong> per cup water; bring to a boil, then gentle simmer <strong>10–20 minutes</strong> covered; strain.</p><p><strong>Safety:</strong> Longer heat extracts more constituents—including bitter or irritating ones. Do not decoct delicate flowers the same way (they often turn flat or harsh).</p></section><section class=\"entry-section\"><h3>Tincture (alcohol extract)</h3><p><strong>What it is:</strong> Plant material macerated in ethanol (or ethanol–water) for weeks, then pressed/strained.</p><p><strong>Educational kitchen pattern (adults):</strong> Often roughly <strong>1 part dried herb by weight to 5 parts liquid by volume</strong> (a common folk “1:5”), using <strong>40–60% alcohol</strong> (80–120 proof vodka-class spirits) for many leafy/aromatic herbs. Roots may need higher proof in professional practice—<strong>this primer does not train you as a pharmacist.</strong></p><p><strong>Steps sketch:</strong> Chop/crush herb → jar → cover completely with alcohol → label → shake daily → wait <strong>2–6 weeks</strong> → strain → bottle in dropper bottles → label with alcohol % and date.</p><p><strong>Safety:</strong> Keep away from children. Not for people who must avoid alcohol. Pregnancy: generally avoid medicinal tinctures unless a clinician directs. Shelf life of a well-made high-proof tincture is often <strong>years</strong> if stored cool/dark; discard if cloudy with growth or strange odor. <strong>Glycerites</strong> (glycerin extracts) are a different method with shorter shelf life—study before substituting.</p></section><section class=\"entry-section\"><h3>Syrup (honey or sugar + strong tea/decoction)</h3><p><strong>What it is:</strong> A sweetened, shelf-stabilized liquid for pleasant sipping (food tradition).</p><p><strong>Safety:</strong> Refrigerate homemade syrups. Typical home fridge life is often discussed as <strong>weeks to a few months</strong> depending on sugar/honey ratio and cleanliness—<strong>when in doubt, discard</strong>. <strong>No honey for infants under 1.</strong> Diabetics: syrups are sugar—ask a clinician. Syrups are <strong>food vehicles</strong>, not disease cures.</p></section><section class=\"entry-section\"><h3>Salve / ointment (oil + beeswax)</h3><p><strong>What it is:</strong> Herbal-infused oil thickened with beeswax for external skin application.</p><p><strong>Basic ratio literacy:</strong> Many home crafters start near <strong>1 oz (28 g) beeswax per 1 cup (240 ml) infused oil</strong>, then adjust firmer/softer. Melt gently, pour into tins, cool, label <strong>EXTERNAL</strong>.</p><p><strong>Safety:</strong> Patch-test. Do not put salves in eyes, deep puncture wounds, or infected wounds that need medical care. Beeswax allergy is possible. Keep lids clean.</p></section><section class=\"entry-section\"><h3>Poultice (fresh or moistened herb on skin)</h3><p><strong>What it is:</strong> Crushed moist plant applied externally, often with a clean cloth.</p><p><strong>Safety:</strong> Short contact; watch for irritation. Do not poultice over broken skin with unknown wild plants. Remove if burning or blistering begins.</p></section><section class=\"entry-section\"><h3>Vinegar (acetic extracts / oxymels)</h3><p><strong>What it is:</strong> Herbs steeped in apple-cider or wine vinegar; sometimes honey is added later (oxymel tradition).</p><p><strong>Safety:</strong> Use food-grade vinegar (~5% acetic acid). Avoid metal lids contacting vinegar long-term (use plastic-lined or glass). Refrigerate if you add fresh garlic/onion or dilute with water/honey. Culinary vinegars are not plague cures or disinfectant substitutes for clinical infection.</p><p>---</p></section>" };
window.RECIPE_LOCALES["en"]["primer-b"] = { title: "Four-step guidance for combining herbs thoughtfully", html: "<p>This is <strong>synergy literacy</strong>, not a license to invent “miracle stacks.”</p><section class=\"entry-section\"><h3>Step 1 — Name one clear traditional purpose</h3><p>Example: “after-meal settling tea,” not “detox your liver and kill pathogens.” Vague mega-goals invite unsafe stacking.</p></section><section class=\"entry-section\"><h3>Step 2 — Choose a simple “lead” herb you already tolerate</h3><p>One familiar culinary or gentle herb first (peppermint, ginger, chamomile, lemon balm). Confirm no allergy and no conflict with your medicines.</p></section><section class=\"entry-section\"><h3>Step 3 — Add at most one or two supportive partners with a related traditional role</h3><ul><li><strong>Aromatic companions</strong> (fennel with mint) for digestive folklore.</li><li><strong>Soothing mucilage companions</strong> (marshmallow leaf <em>instead of</em> overharvested slippery elm when possible).</li><li><strong>Flavor balancers</strong> (a pinch of cinnamon in golden milk)—flavor is stewardship, not a drug claim.</li></ul><p>Avoid mixing many strong actives (laxatives + sedatives + stimulant bitters + EOs) “because more is better.”</p></section><section class=\"entry-section\"><h3>Step 4 — Review cautions as a set, then reassess</h3><p>Ask: pregnancy? children? blood thinners? surgery soon? alcohol sensitivity? skin integrity? If any answer is uncertain, <strong>simplify to food</strong> or <strong>ask a clinician</strong>. Keep a short use journal (what, how much, how you felt). Stop if you feel worse. Combining herbs does <strong>not</strong> multiply holiness or guarantee benefit—humility is part of wisdom (cf. the spirit of Proverbs’ praise of knowledge with prudence).</p><p>---</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-garden-settling-digestive-tea"] = { title: "1. Garden Settling Digestive Tea", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/traditional)</h3><p>A mild after-meal aromatic tea in the long kitchen tradition of mint-and-seed digestives—comfort folklore, not a diagnosis of “IBS” or ulcer disease.</p></section><section class=\"entry-section\"><h3 data-i18n=\"ingredients\">Ingredients (1 mug)</h3><ul><li>1 tsp dried peppermint leaf (<em>Mentha × piperita</em>)</li><li>1 tsp crushed fennel seed (<em>Foeniculum vulgare</em>)</li><li>8 oz (240 ml) near-boiling water</li><li>Optional: thin slice fresh ginger or a few lemon balm leaves</li></ul></section><section class=\"entry-section\"><h3 data-i18n=\"steps\">Steps</h3><ol><li>1. Combine herbs in a cup or teapot.</li><li>2. Pour hot water; cover 10 minutes.</li><li>3. Strain; sip warm after a meal.</li><li>4. Do not sweeten heavily if you are watching blood sugar—optional honey only for adults/older children per clinician guidance.</li></ol></section><section class=\"entry-section\"><h3 data-i18n=\"storage\">Storage</h3><p>Drink fresh. Refrigerate leftovers up to 24 hours; discard if off.</p></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p>Peppermint may worsen reflux in some people. Fennel is generally culinary, but medicinal amounts in pregnancy warrant clinician advice; rare Apiaceae allergies exist. Essential oil of peppermint/fennel is <strong>not</strong> a substitute for this tea and is <strong>not</strong> for casual internal use.</p></section><section class=\"entry-section\"><h3>Creation note</h3><p>Aromatic garden herbs fit the larger biblical pattern of plants given for food and careful living (Genesis 1:29)—without inventing a “digestive miracle verse.”</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-quiet-evening-lemon-balm-chamomile-cup"] = { title: "2. Quiet Evening Lemon Balm & Chamomile Cup", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/traditional)</h3><p>A gentle evening cup associated in folk herbalism with calm and settling—not a treatment for anxiety disorders, insomnia disease, or depression.</p></section><section class=\"entry-section\"><h3 data-i18n=\"ingredients\">Ingredients (1 mug)</h3><ul><li>1 tsp dried lemon balm (<em>Melissa officinalis</em>)</li><li>1 tsp dried German chamomile flowers (<em>Matricaria chamomilla</em>)</li><li>8 oz (240 ml) near-boiling water</li></ul></section><section class=\"entry-section\"><h3 data-i18n=\"steps\">Steps</h3><ol><li>1. Place herbs in a covered mug or pot.</li><li>2. Steep 5–10 minutes (chamomile can turn bitter if over-steeped for some palates).</li><li>3. Strain; sip in the evening away from screens if you like a wind-down ritual.</li><li>4. Optional adult honey drizzle.</li></ol></section><section class=\"entry-section\"><h3 data-i18n=\"storage\">Storage</h3><p>Fresh use preferred.</p></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p>Chamomile is in the daisy family—avoid if you have strong ragweed/chrysanthemum allergies. Lemon balm may theoretically affect thyroid labs/meds in concentrated use—ask if you have thyroid disease. Sedating stacks with prescription sleep meds need clinician advice. Not a substitute for mental-health care.</p></section><section class=\"entry-section\"><h3>Scripture/creation note</h3><p>None forced; gratitude for evening rest is enough.</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-mullein-leaf-respiratory-steam-cup-tea"] = { title: "3. Mullein Leaf Respiratory Steam-Cup (tea)", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/traditional)</h3><p>Traditional folk use of mullein leaf as a soothing respiratory-season tea/steam aroma—<strong>not</strong> a pneumonia, COVID, asthma, or tuberculosis treatment.</p></section><section class=\"entry-section\"><h3 data-i18n=\"ingredients\">Ingredients (1 mug)</h3><ul><li>1–2 tsp dried mullein leaf (<em>Verbascum thapsus</em>), preferably cut-and-sifted</li><li>8–10 oz water</li><li>Fine strainer or coffee filter (mullein hairs can irritate throats)</li></ul></section><section class=\"entry-section\"><h3 data-i18n=\"steps\">Steps</h3><ol><li>1. Pour hot water over leaf; cover 10–15 minutes.</li><li>2. Strain <strong>very well</strong> through a fine filter to remove irritating hairs.</li><li>3. Sip warm, or inhale steam cautiously from a safe distance (no burns).</li><li>4. Limit to short seasonal folk use unless a clinician advises otherwise.</li></ol></section><section class=\"entry-section\"><h3 data-i18n=\"storage\">Storage</h3><p>Fresh.</p></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p>Do not use mullein <em>seeds</em> or unfiltered fuzzy leaf casually. Asthma and serious breathing problems need medical care—tea is not an inhaler. Pregnancy: ask first. Smoke folklore exists historically; <strong>this recipe does not encourage smoking herbs.</strong></p></section>" };
window.RECIPE_LOCALES["en"]["recipe-fresh-ginger-root-comfort-tea"] = { title: "4. Fresh Ginger Root Comfort Tea", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/traditional)</h3><p>Classic kitchen tea for chilly days and stomach unsettledness folklore—food-level education, not prescription antiemetic therapy.</p></section><section class=\"entry-section\"><h3 data-i18n=\"ingredients\">Ingredients (1 mug)</h3><ul><li>3–5 thin slices fresh ginger root (~1–2 tsp grated)</li><li>8–10 oz water</li><li>Optional: lemon slice; adult honey to taste</li></ul></section><section class=\"entry-section\"><h3 data-i18n=\"steps\">Steps</h3><ol><li>1. Simmer slices gently 10 minutes (decoction-style) or steep grated ginger in near-boiling water 10 minutes.</li><li>2. Strain; add lemon/honey if desired.</li><li>3. Sip warm.</li></ol></section><section class=\"entry-section\"><h3 data-i18n=\"storage\">Storage</h3><p>Fresh; refrigerated leftover tea ~24 hours.</p></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p>Ginger can interact with blood thinners and may bother gallstones or reflux in some people—ask a clinician if relevant. Medicinal megadoses in pregnancy belong to clinical guidance, not internet challenges. Ginger essential oil is <strong>not</strong> for casual internal use.</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-rosemary-folklore-clarity-tea-honest-limits"] = { title: "5. Rosemary Folklore Clarity Tea (honest limits)", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/traditional)</h3><p>Culinary rosemary tea linked in Mediterranean folklore with “remembrance” and alertness symbolism—<strong>honest limit:</strong> this is not a proven Alzheimer’s drug or IQ booster.</p></section><section class=\"entry-section\"><h3 data-i18n=\"ingredients\">Ingredients (1 mug)</h3><ul><li>1 tsp dried rosemary leaf (<em>Salvia rosmarinus</em> / <em>Rosmarinus officinalis</em>), crumbled</li><li>8 oz near-boiling water</li></ul></section><section class=\"entry-section\"><h3 data-i18n=\"steps\">Steps</h3><ol><li>1. Steep covered 5–8 minutes (longer gets quite bitter/camphorous).</li><li>2. Strain; sip occasionally as a culinary herbal tea.</li><li>3. Pair with a walk and good sleep—folklore without magical thinking.</li></ol></section><section class=\"entry-section\"><h3 data-i18n=\"storage\">Storage</h3><p>Fresh.</p></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p>Avoid large medicinal amounts in pregnancy. Epilepsy or strong camphor sensitivity: ask a clinician. Rosemary <strong>essential oil</strong> is concentrated—aromatic/topical dilute only, <strong>not</strong> oral DIY. People with high blood pressure on meds should clear herbal experiments with a clinician.</p></section><section class=\"entry-section\"><h3>Creation note</h3><p>Rosemary is a gift of Mediterranean kitchens; memory folklore is cultural poetry, not a clinical claim.</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-spring-nettle-leaf-food-like-tea"] = { title: "6. Spring Nettle Leaf Food-Like Tea", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/traditional)</h3><p>Nourishing food-like infusion from dried stinging nettle leaf—mineral-rich folk food tradition, not a “blood cleanser” cure.</p></section><section class=\"entry-section\"><h3 data-i18n=\"ingredients\">Ingredients</h3><ul><li>1–2 tsp dried nettle leaf (<em>Urtica dioica</em>) per 8 oz water</li></ul></section><section class=\"entry-section\"><h3 data-i18n=\"steps\">Steps</h3><ol><li>1. Pour near-boiling water over dried leaf; cover 10–15 minutes (some steep longer for a “nourishing” style—flavor will be deeper/earthier).</li><li>2. Strain; drink as a savory green tea.</li><li>3. Optional: pinch of mint to soften the grassy taste.</li></ol></section><section class=\"entry-section\"><h3 data-i18n=\"storage\">Storage</h3><p>Fresh or refrigerate up to 24 hours.</p></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p>Use <strong>dried</strong> or thoroughly cooked leaf—fresh raw nettles sting. May be diuretic; ask if you take blood pressure, diabetes, or blood-thinning medicines, or have kidney disease. Rare allergy possible. Forage only with expert ID (look-alikes exist in some regions).</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-kitchen-turmeric-golden-milk"] = { title: "7. Kitchen Turmeric Golden Milk", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/traditional)</h3><p>A warm spiced milk drink from South Asian–inspired kitchen tradition—comfort food with turmeric, not an “anti-inflammatory drug” or cancer protocol.</p></section><section class=\"entry-section\"><h3 data-i18n=\"ingredients\">Ingredients (1 mug)</h3><ul><li>1 cup (240 ml) milk of choice (dairy or unsweetened plant milk)</li><li>½–1 tsp turmeric powder (<em>Curcuma longa</em>)</li><li>Tiny pinch black pepper (traditional pairing folklore for culinary turmeric)</li><li>Optional: ¼ tsp cinnamon; slice fresh ginger; adult honey to taste</li></ul></section><section class=\"entry-section\"><h3 data-i18n=\"steps\">Steps</h3><ol><li>1. Whisk turmeric (and optional spices) into a splash of cold milk to make a smooth paste.</li><li>2. Warm the remaining milk gently—do not scorched-boil.</li><li>3. Whisk in the paste; simmer very gently 3–5 minutes.</li><li>4. Sweeten lightly if desired; sip warm.</li></ol></section><section class=\"entry-section\"><h3 data-i18n=\"storage\">Storage</h3><p>Best fresh; refrigerate leftovers ~24 hours; reheat once.</p></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p>Turmeric/curcumin supplements are <strong>not</strong> the same as kitchen powder—high-dose extracts can interact with blood thinners and affect gallbladder disease. Pregnancy: keep to food amounts unless clinician directs. Stains clothing and counters. <strong>Never</strong> present golden milk as an anti-cancer recipe.</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-dark-berries-immune-season-elderberry-syrup-food-tradition"] = { title: "8. Dark Berries Immune-Season Elderberry Syrup (food tradition)", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/traditional)</h3><p>A cooked elderberry syrup in the cold-season food tradition of European kitchens—<strong>not</strong> a flu cure, COVID treatment, or vaccine replacement.</p></section><section class=\"entry-section\"><h3>Ingredients (about 2–3 cups syrup, varies)</h3><ul><li>1 cup dried black elderberries (<em>Sambucus nigra</em> ripe berries only) <strong>or</strong> ~2 cups frozen ripe black elderberries</li><li>3 cups water</li><li>1 cinnamon stick (optional)</li><li>3–5 slices fresh ginger (optional)</li><li>1 cup honey (or to taste; add <strong>off heat</strong>)</li></ul></section><section class=\"entry-section\"><h3 data-i18n=\"steps\">Steps</h3><ol><li>1. Simmer berries (and optional spices) in water about 30–45 minutes until liquid reduces by roughly one-third to one-half.</li><li>2. Mash lightly; strain through a fine mesh or cloth (avoid squirting into eyes).</li><li>3. Cool until warm, not hot; stir in honey.</li><li>4. Bottle in clean glass; label and date; refrigerate.</li></ol></section><section class=\"entry-section\"><h3 data-i18n=\"storage\">Storage</h3><p>Refrigerate; typical home teaching often aims to use within <strong>1–3 months</strong>—discard at mold, ferment fizz, or off odor.</p></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p>Use only <strong>ripe cooked</strong> black elderberries from trusted <em>S. nigra</em> sources. Raw berries, leaves, bark, and other <em>Sambucus</em> parts can cause nausea. Autoimmune disease or immunosuppressant drugs: ask a clinician before “immune” folkloric use. <strong>No honey for infants under 1.</strong> Diabetes: sugar load matters. This is food tradition education—not an antiviral drug claim.</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-garlic-in-honey-folk-preserve-food"] = { title: "9. Garlic-in-Honey Folk Preserve (food)", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/traditional)</h3><p>Peeled garlic cloves preserved in honey as a folk food condiment—culinary interest, not an antibiotic replacement.</p></section><section class=\"entry-section\"><h3 data-i18n=\"ingredients\">Ingredients</h3><ul><li>Peeled garlic cloves to loosely fill a small clean jar (about 1 cup cloves)</li><li>Enough raw or pasteurized honey to cover completely</li></ul></section><section class=\"entry-section\"><h3 data-i18n=\"steps\">Steps</h3><ol><li>1. Use dry, unblemished cloves; optional light crush.</li><li>2. Place in jar; cover fully with honey; release air bubbles with a clean chopstick.</li><li>3. Lid loosely at first if very fresh garlic releases gases; then seal.</li><li>4. Store cool/dark; cloves soften over days to weeks. Use as a food drizzle/condiment.</li></ol></section><section class=\"entry-section\"><h3 data-i18n=\"storage\">Storage</h3><p>Cool pantry or fridge; watch for unusual foaming or mold—discard if suspicious. Some prefer refrigeration for caution.</p></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p>Botulism risk conversations exist around low-acid garlic-in-oil; honey-garlic is a different matrix but still requires cleanliness and common sense—<strong>do not give to infants.</strong> Garlic can increase bleeding tendency and interact with HIV meds and anticoagulants—ask if relevant. Food use ≠ treating infection in place of medical care.</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-honey-onion-household-cough-syrup-food-tradition"] = { title: "10. Honey-Onion Household Cough Syrup (food tradition)", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/traditional)</h3><p>Old household sweet onion-and-honey syrup for soothing sore-throat folklore—food tradition, not pneumonia care.</p></section><section class=\"entry-section\"><h3 data-i18n=\"ingredients\">Ingredients</h3><ul><li>1 medium onion, thinly sliced</li><li>Enough honey to cover slices in a jar (about ½–1 cup)</li></ul></section><section class=\"entry-section\"><h3 data-i18n=\"steps\">Steps</h3><ol><li>1. Layer onion in a clean jar; cover with honey.</li><li>2. Let sit 2–4 hours (or overnight in the fridge) until syrupy liquid forms.</li><li>3. Strain liquid into a clean bottle; discard solids or use in cooking if you wish.</li><li>4. Adults: small spoonfuls as a soothing food syrup. Older children: only with clinician/parent judgment; <strong>never under age 1 (honey).</strong></li></ol></section><section class=\"entry-section\"><h3 data-i18n=\"storage\">Storage</h3><p>Refrigerate; use within ~1 week; discard if off.</p></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p>Persistent cough, high fever, or breathing trouble → clinician. Honey not for infants. Onion can bother reflux.</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-sunshine-calendula-infused-oil"] = { title: "11. Sunshine Calendula Infused Oil", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/traditional)</h3><p>Oil infused with calendula petals for external skin-comfort folklore—dry patches and chapped-skin craft, not infection treatment.</p></section><section class=\"entry-section\"><h3 data-i18n=\"ingredients\">Ingredients</h3><ul><li>1 cup dried calendula petals (<em>Calendula officinalis</em>)</li><li>1¼–1½ cups olive oil (enough to cover by ~1 inch)</li></ul></section><section class=\"entry-section\"><h3>Steps (gentle warm method)</h3><ol><li>1. Place petals in a clean dry jar; cover completely with oil.</li><li>2. Set jar in a warm water bath or yogurt-maker-type warmth <strong>well below frying heat</strong> for several hours, or sunny-window folk method for 1–2 weeks (avoid overheating/spoiling).</li><li>3. Shake gently when you remember.</li><li>4. Strain through cloth; bottle; label <strong>EXTERNAL</strong> with date.</li></ol></section><section class=\"entry-section\"><h3 data-i18n=\"storage\">Storage</h3><p>Cool/dark; often months if dry herb and clean process—discard if cloudy, moldy, or rancid-smelling.</p></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p>Daisy-family allergy possible. External only. Do not use in eyes. Deep or infected wounds need medical care.</p></section><section class=\"entry-section\"><h3>Creation note</h3><p>Marigold-bright petals are a humble garden mercy for hands that work the soil.</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-calendula-garden-salve"] = { title: "12. Calendula Garden Salve", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/traditional)</h3><p>Beeswax-thickened calendula oil for external chapped-skin craft.</p></section><section class=\"entry-section\"><h3 data-i18n=\"ingredients\">Ingredients</h3><ul><li>1 cup calendula infused oil (Recipe 11)</li><li>~1 oz (28 g) beeswax (pastilles or grated)—adjust for firmer/softer set</li><li>Optional: 1–2 tsp vitamin E oil as antioxidant folklore for shelf life (not a drug claim)</li></ul></section><section class=\"entry-section\"><h3 data-i18n=\"steps\">Steps</h3><ol><li>1. Gently melt oil + beeswax in a double boiler until just combined.</li><li>2. Remove from heat; optional vitamin E.</li><li>3. Pour into clean tins; cool undisturbed.</li><li>4. Label <strong>EXTERNAL ONLY</strong>, date, ingredients.</li></ol></section><section class=\"entry-section\"><h3 data-i18n=\"storage\">Storage</h3><p>Cool/dark; often many months; discard if smell turns rancid.</p></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p>Patch-test. Beeswax allergy possible. Not for deep wounds, animal bites, or eye use.</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-aloe-leaf-gel-external-cool-note"] = { title: "13. Aloe Leaf Gel — External Cool Note", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/traditional)</h3><p>Fresh inner-leaf gel used externally in many cultures to soothe sunburned or irritated skin—educational external note, not burn-unit care.</p></section><section class=\"entry-section\"><h3 data-i18n=\"ingredients\">Ingredients</h3><ul><li>1 mature outer leaf of <em>Aloe vera</em> (food-cosmetic grade plant, pesticide-aware)</li></ul></section><section class=\"entry-section\"><h3 data-i18n=\"steps\">Steps</h3><ol><li>1. Rinse leaf; trim spikes.</li><li>2. Fillet to expose clear inner gel; avoid yellow latex just under the skin when possible (latex is a stimulant laxative and can irritate).</li><li>3. Scoop clear gel; optional brief blend for smoothness.</li><li>4. Apply a thin layer <strong>externally</strong> to intact sun-warmed skin; refrigerate leftover gel in a clean jar and use within a few days.</li></ol></section><section class=\"entry-section\"><h3 data-i18n=\"storage\">Storage</h3><p>Fridge; few days; discard if pink/brown slimy spoilage appears.</p></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p>Patch-test. Do not use on severe burns (seek medical care). Latex orally is <strong>not</strong> recommended here—stimulant laxative risks, pregnancy contraindication in traditional teaching, and regulatory safety concerns. Essential oils do not belong in this gel for casual “stronger” experiments.</p></section><section class=\"entry-section\"><h3>Scripture note</h3><p>Biblical “aloes” in some verses likely refer to fragrant eaglewood-type aromatics, <strong>not</strong> identical to modern <em>Aloe vera</em> gel—teach the distinction honestly (see Aloes monograph).</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-plantain-leaf-field-poultice"] = { title: "14. Plantain Leaf Field Poultice", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/traditional)</h3><p>Classic folk external poultice from broadleaf or ribwort plantain for minor scrapes and insect-bite folklore—first-aid adjacent education, not ER care.</p></section><section class=\"entry-section\"><h3 data-i18n=\"ingredients\">Ingredients</h3><ul><li>Several clean <em>Plantago major</em> or <em>P. lanceolata</em> leaves (positive ID required)</li><li>Clean water; clean cloth</li></ul></section><section class=\"entry-section\"><h3 data-i18n=\"steps\">Steps</h3><ol><li>1. Wash leaves well.</li><li>2. Chew briefly <strong>only if</strong> you trust plant ID and your mouth is healthy—or crush with a clean spoon to bruise and moisten.</li><li>3. Apply to intact or very minor superficial skin areas; cover lightly with cloth 10–20 minutes.</li><li>4. Remove; wash skin; watch for irritation.</li></ol></section><section class=\"entry-section\"><h3 data-i18n=\"storage\">Storage</h3><p>Use fresh leaves; do not store a chewed poultice.</p></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p>Wrong plant ID is dangerous—do not improvise if unsure. Deep punctures, signs of infection, tick bites of concern, or animal bites → clinician. Do not use mouth-chewed poultices on people immunocompromised without clinical advice.</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-comfrey-leaf-external-only-salve-note"] = { title: "15. Comfrey Leaf External-Only Salve Note", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/traditional)</h3><p>Teaching entry for <strong>external-only</strong> comfrey craft literacy—and a hard line against internal use.</p></section><section class=\"entry-section\"><h3>Ingredients (educational external pattern)</h3><ul><li>1 cup dried comfrey leaf (<em>Symphytum officinale</em>) infused in olive oil (same method as calendula oil)</li><li>Beeswax to salve consistency (~1 oz per cup oil as a starting point)</li></ul></section><section class=\"entry-section\"><h3 data-i18n=\"steps\">Steps</h3><ol><li>1. Infuse <strong>leaf</strong> oil with dry herb and clean process; strain.</li><li>2. Make salve as in Recipe 12.</li><li>3. Label boldly: <strong>EXTERNAL ONLY — DO NOT INGEST</strong>.</li><li>4. Use sparingly on unbroken skin for traditional bruise/sprain folklore education.</li></ol></section><section class=\"entry-section\"><h3 data-i18n=\"storage\">Storage</h3><p>Cool/dark; discard if rancid.</p></section><section class=\"entry-section\"><h3>Cautions (critical)</h3><p>Comfrey contains <strong>pyrrolizidine alkaloids (PAs)</strong> linked to serious liver toxicity when taken internally. <strong>No comfrey tea, no comfrey smoothies, no internal tinctures in this curriculum.</strong> Avoid on deep wounds or broken skin where absorption rises. Avoid in pregnancy, nursing, and in children. Prefer PA-reduced professional products if a clinician ever recommends a comfrey-type topical—and still treat as external-only teaching.</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-lavender-linen-sachet-dilute-topical-note"] = { title: "16. Lavender Linen Sachet & Dilute Topical Note", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/traditional)</h3><p>Dried lavender for linen fragrance and <em>highly diluted</em> topical aroma—not oral essential-oil medicine.</p></section><section class=\"entry-section\"><h3 data-i18n=\"ingredients\">Ingredients</h3><ul><li>½–1 cup dried lavender buds (<em>Lavandula angustifolia</em>) for sachets</li><li>For dilute topical (adults): 1 drop lavender essential oil in 1 tsp (5 ml) carrier oil (approximate <strong>1%</strong> ballpark)—or skip EO entirely and rub dried buds in hands for scent</li></ul></section><section class=\"entry-section\"><h3>Steps (sachet)</h3><ol><li>1. Fill small cloth bags with dried buds; tie closed.</li><li>2. Place in drawer or under pillow (aroma preference varies).</li><li>3. Refresh when scent fades.</li></ol></section><section class=\"entry-section\"><h3>Steps (dilute topical optional)</h3><ol><li>1. Mix EO into carrier; patch-test inner arm 24 hours.</li><li>2. Dab on pulse-point skin if tolerated.</li><li>3. Wash hands after; keep away from eyes.</li></ol></section><section class=\"entry-section\"><h3 data-i18n=\"storage\">Storage</h3><p>Dried buds airtight/cool; EO bottles dark/cool, childproof.</p></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p><strong>Do not ingest lavender essential oil casually.</strong> Some people get headaches from strong scent. Pets (especially cats) can be sensitive to EOs—ventilate; do not apply to animals without veterinary guidance. Children: stick to dried sachets unless a clinician advises.</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-rosemary-garden-hair-rinse"] = { title: "17. Rosemary Garden Hair Rinse", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/traditional)</h3><p>Diluted rosemary tea as a final hair rinse in folk cosmetic tradition—scalp freshness folklore, not a medical alopecia cure.</p></section><section class=\"entry-section\"><h3 data-i18n=\"ingredients\">Ingredients</h3><ul><li>2 Tbsp dried rosemary</li><li>2 cups water</li><li>Optional: 1 Tbsp apple-cider vinegar in the cooled rinse (scalp folk tradition)</li></ul></section><section class=\"entry-section\"><h3 data-i18n=\"steps\">Steps</h3><ol><li>1. Simmer rosemary in water 10–15 minutes; cool; strain well.</li><li>2. After normal shampoo/condition, pour rinse over hair/scalp.</li><li>3. Do not rinse out unless you prefer to; style as usual.</li><li>4. Use occasionally; discontinue if irritation.</li></ol></section><section class=\"entry-section\"><h3 data-i18n=\"storage\">Storage</h3><p>Refrigerate tea rinse up to 3 days; discard if cloudy/off.</p></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p>Keep out of eyes. Scalp conditions (psoriasis, infection) need clinical care. EO rinses are a different, higher-risk craft—this recipe uses tea, not straight essential oil.</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-four-aromatics-historical-vinegar-culinary-cleaning-adjacent"] = { title: "18. Four Aromatics Historical Vinegar (culinary / cleaning-adjacent)", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/traditional)</h3><p>An original aromatic vinegar in the <em>spirit</em> of early-modern “four thieves” folklore—<strong>history literacy + culinary/cleaning-adjacent household use</strong>. It is <strong>not</strong> a plague cure, antiviral drug, or substitute for vaccines, antibiotics, or public-health measures.</p></section><section class=\"entry-section\"><h3>Historical honesty</h3><p>Stories of thieves using herbal vinegar during plague years are later folklore layered on real aromatic-vinegar traditions. Recipes varied widely; modern branded products are proprietary. This formula is a <strong>fresh educational reconstruction</strong>, not a copy of any book’s blend.</p></section><section class=\"entry-section\"><h3 data-i18n=\"ingredients\">Ingredients</h3><ul><li>2 cups (480 ml) raw apple-cider vinegar (~5% acidity)</li><li>1 Tbsp dried rosemary</li><li>1 Tbsp dried sage</li><li>1 Tbsp dried lavender buds</li><li>1 Tbsp dried thyme</li><li>2–3 peeled garlic cloves (optional; increases spoilage caution)</li><li>1 small cinnamon stick (optional)</li></ul></section><section class=\"entry-section\"><h3 data-i18n=\"steps\">Steps</h3><ol><li>1. Place herbs (and optional garlic/cinnamon) in a clean glass jar.</li><li>2. Cover with vinegar by at least 1 inch; seal with non-metal-contact lid.</li><li>3. Steep 2–4 weeks, shaking occasionally; keep cool/dark.</li><li>4. Strain; bottle; label “culinary aromatic vinegar — not a medicine.”</li></ol></section><section class=\"entry-section\"><h3 data-i18n=\"storage\">Storage</h3><p>Cool pantry if herb-only; refrigerate if garlic was used; use within a few months; discard if mold appears.</p></section><section class=\"entry-section\"><h3>Suggested educational uses</h3><p>Salad dressings (diluted with oil); as a kitchen counter wipe <strong>after</strong> proper cleaning for scent (vinegar is not a hospital disinfectant claim). Do <strong>not</strong> drink as a “detox plague tonic.”</p></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p>External wipe: dilute; don’t soak skin. Culinary: garlic-vinegar not for infants; interactions as with garlic. Pregnancy: food-level herbs usually differ from gulping medicinal vinegars—ask if unsure.</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-simple-kitchen-digestive-bitters-aromatic-vinegar-style"] = { title: "19. Simple Kitchen Digestive Bitters (aromatic vinegar style)", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/traditional)</h3><p>A gentle aromatic bitter-sour vinegar for before-meal folklore (appetite/digestive cue)—not a liver “cleanse” or parasite protocol.</p></section><section class=\"entry-section\"><h3 data-i18n=\"ingredients\">Ingredients</h3><ul><li>1½ cups apple-cider vinegar</li><li>1 Tbsp dried orange peel (food-grade)</li><li>1 tsp gentian root <strong>or</strong> omit gentian and use 1 tsp dried dandelion root for a milder teaching version</li><li>1 tsp fennel seed</li><li>½ tsp ginger, dried, or a few fresh slices</li><li>Optional: 2–4 Tbsp honey after straining (oxymel-style)</li></ul></section><section class=\"entry-section\"><h3 data-i18n=\"steps\">Steps</h3><ol><li>1. Combine botanicals in a jar; cover with vinegar.</li><li>2. Steep 2–3 weeks; shake now and then.</li><li>3. Strain; optional honey while liquid is not hot.</li><li>4. Adults: traditionally a <strong>small</strong> taste (e.g., 1 teaspoon in a little water) before meals—<strong>stop if it upsets you.</strong></li></ol></section><section class=\"entry-section\"><h3 data-i18n=\"storage\">Storage</h3><p>Cool/dark; months typical for vinegar extracts; discard if spoiled.</p></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p>Strong bitters can aggravate ulcers, reflux, or nausea. Gentian is intensely bitter—omit if too harsh. Pregnancy: avoid medicinal bitters unless clinician directs. Not for children as a “tonic experiment.” This is not antibiotic therapy.</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-levant-table-za-atar-style-herb-blend"] = { title: "20. Levant Table Za’atar-Style Herb Blend", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/traditional)</h3><p>Culinary sesame-herb-spice blend inspired by Levantine table traditions—food joy, not a medical formula. Regional za’atar recipes vary; this is an <strong>original kitchen teaching blend</strong>, not a branded copy.</p></section><section class=\"entry-section\"><h3 data-i18n=\"ingredients\">Ingredients (small jar)</h3><ul><li>3 Tbsp dried thyme (or a mix of thyme + oregano)</li><li>1 Tbsp dried marjoram or additional oregano</li><li>2 Tbsp toasted sesame seeds</li><li>1–2 tsp sumac</li><li>½–1 tsp fine salt (optional)</li><li>Optional pinch roasted ground cumin</li></ul></section><section class=\"entry-section\"><h3 data-i18n=\"steps\">Steps</h3><ol><li>1. Lightly toast sesame seeds until fragrant; cool.</li><li>2. Crumble herbs; mix with sumac, sesame, and optional salt/cumin.</li><li>3. Taste; adjust tartness (sumac) and salt.</li><li>4. Serve with olive oil and bread as a food dip.</li></ol></section><section class=\"entry-section\"><h3 data-i18n=\"storage\">Storage</h3><p>Airtight jar, cool/dark, ~1–3 months for best aroma.</p></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p>Food allergies (sesame). Salt-sensitive diets: omit salt. Culinary only.</p></section><section class=\"entry-section\"><h3>Creation / culture note</h3><p>Sharing bread and oil is kin to ancient hospitality themes in Scripture’s world—without claiming this exact spice jar appears in a verse.</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-avicenna-inspired-rosewater-educational-note"] = { title: "21. Avicenna-Inspired Rosewater Educational Note", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/traditional)</h3><p>Historical literacy around rosewater (<em>maa’ ward</em>) in Persian/Islamic medical and culinary heritage associated with figures like Ibn Sina (Avicenna)—<strong>aromatic/culinary education</strong>, not a reconstruction of a copyrighted modern hydrosol brand protocol.</p></section><section class=\"entry-section\"><h3>Uncertainty</h3><p>True hydrosol production uses steam distillation equipment and yield/safety know-how. Home “simmer rose petals then bottle” methods produce a <strong>fragile aromatic water</strong> that spoils quickly and is <strong>not</strong> identical to commercial steam-distilled rosewater.</p></section><section class=\"entry-section\"><h3>Gentle home aromatic water (short-shelf educational)</h3><ul><li>1–2 cups pesticide-free fragrant rose petals (<em>Rosa × damascena</em> or culinary roses—not florist pesticide roses)</li><li>Water just to cover</li></ul></section><section class=\"entry-section\"><h3 data-i18n=\"steps\">Steps</h3><ol><li>1. Simmer very gently, covered, 15–20 minutes; do not hard-boil to mud.</li><li>2. Cool; strain; refrigerate immediately in clean glass.</li><li>3. Use within <strong>several days</strong> as a fridge aromatic rinse for face/skin <strong>patch-test first</strong>, or a drop in adult desserts—prefer commercial food-grade rosewater for cooking reliability.</li><li>4. Discard at cloudiness or sour spoilage.</li></ol></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p>Spoilage risk is high—when unsure, buy reputable food-grade rosewater. External splash: avoid eyes. Essential oil of rose is costly and concentrated—<strong>not</strong> for casual internal use. Pregnancy: food-level culinary rosewater differs from medicinal claims—keep humble.</p></section><section class=\"entry-section\"><h3>Historical note</h3><p>Celebrate the intellectual history of distillation without pretending a saucepan equals a medieval stillroom.</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-kyphi-inspired-temple-aromatics-incense-note"] = { title: "22. Kyphi-Inspired Temple Aromatics Incense Note", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/traditional)</h3><p>Aromatic-only educational incense note inspired by Egyptian <em>kyphi</em> traditions and biblical incense botanicals (frankincense, myrrh, and hyssop-adjacent aromatics)—<strong>smell and history</strong>, not lung medicine or mystical medical protocol.</p></section><section class=\"entry-section\"><h3>Uncertainty</h3><p>Ancient kyphi recipes were complex (wine, honey, resins, many aromatics) and varied by source text. This is a <strong>simplified modern aromatic study blend</strong>, not a museum-accurate formula and not copied from a copyrighted ritual book.</p></section><section class=\"entry-section\"><h3>Simple resin study blend (ventilate)</h3><ul><li>1 tsp frankincense tears</li><li>½ tsp myrrh tears</li><li>Optional: pinch dried hyssop or cinnamon bark for educational aroma comparison</li><li>Charcoal disc designed for incense <strong>or</strong> observe resins in a purpose-made warmer per device instructions</li></ul></section><section class=\"entry-section\"><h3 data-i18n=\"steps\">Steps</h3><ol><li>1. Open windows; remove children/pets with smoke sensitivity from the room.</li><li>2. Light charcoal carefully on a fireproof burner; wait until ashed over—or use an electric resin warmer.</li><li>3. Place a <strong>tiny</strong> amount of resin; observe aroma briefly.</li><li>4. Extinguish safely; never leave burning incense unattended.</li></ol></section><section class=\"entry-section\"><h3 data-i18n=\"storage\">Storage</h3><p>Resins in airtight jars, cool/dry.</p></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p><strong>Smoke irritates lungs.</strong> Avoid with asthma, infants, pregnancy smoke exposure concerns, or smoke alarms/fire risk. This is <strong>not</strong> antimicrobial therapy, deliverance “protocol,” or a substitute for pastoral care. Biblical incense has worship history (e.g., frankincense in Matthew 2:11 as gift; temple incense laws in Exodus)—teach reverence and safety together, not DIY medical mysticism.</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-olive-oil-anointing-pastoral-note-james-5"] = { title: "23. Olive Oil Anointing Pastoral Note (James 5)", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/pastoral)</h3><p>Olive oil as a <strong>faith practice</strong> of prayer and care in Christian communities, following the pastoral pattern of James 5—<strong>not</strong> a medical protocol, pharmaceutical, or guaranteed physical cure.</p></section><section class=\"entry-section\"><h3 data-i18n=\"ingredients\">Ingredients</h3><ul><li>A small amount of pure olive oil in a clean vial set aside for prayer use</li></ul></section><section class=\"entry-section\"><h3 data-i18n=\"steps\">Pastoral steps (educational description—not a liturgy mandate)</h3><ol><li>1. Elders/pastors and the sick person gather in prayer as the community discerns.</li><li>2. Oil may be applied lightly (forehead or head) <strong>with consent</strong>, while praying.</li><li>3. Seek medical care in parallel—faith and medicine are not enemies.</li><li>4. Keep oil clean; do not “prescribe” herbs under the name of anointing.</li></ol></section><section class=\"entry-section\"><h3 data-i18n=\"storage\">Storage</h3><p>Fresh culinary olive oil, cool/dark; replace if rancid.</p></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p>This is <strong>sacramental/pastoral symbolism and prayer</strong>, not a treatment claim. Do not delay emergency care. Skin allergy to olive oil is uncommon but possible. Do not add random essential oils to “supercharge” anointing—that confuses categories and can harm skin.</p></section><section class=\"entry-section\"><h3>Scripture note (honest)</h3><p>“Is anyone among you sick? Let them call the elders of the church to pray over them and anoint them with oil in the name of the Lord” (James 5:14). The passage centers <strong>prayer and community</strong>, not a pharmacy formula.</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-willow-bark-caution-prefer-clinician-otc-aspirin-literacy"] = { title: "24. Willow Bark Caution — Prefer Clinician / OTC Aspirin Literacy", html: "<section class=\"entry-section\"><h3>Purpose (educational)</h3><p>Teach why this curriculum <strong>does not</strong> give a DIY willow-bark tea dosing recipe for pain/fever.</p></section><section class=\"entry-section\"><h3>Why caution instead of a recipe</h3><ul><li>Willow bark (<em>Salix</em> spp.) contains salicylate-related compounds historically linked to aspirin’s story—but <strong>concentration varies</strong> by species, harvest, and preparation.</li><li>Aspirin and salicylates have clear <strong>toxicity, bleeding, Reye’s syndrome (children/teens with viral illness), pregnancy, ulcer, and drug-interaction</strong> issues.</li><li>Measuring bark tea at home is a poor substitute for labeled dose forms.</li></ul></section><section class=\"entry-section\"><h3>Prefer</h3><ul><li>Clinician guidance for pain/fever.</li><li>Labeled OTC aspirin <strong>only</strong> when appropriate for the person (age, pregnancy status, bleeding risk, viral illness in youth, etc.)—read labels; ask a pharmacist.</li><li>Non-drug comfort measures (hydration, rest) when suitable.</li></ul></section><section class=\"entry-section\"><h3>Do not</h3><p>Boil random backyard willow for “natural aspirin.” Do not give salicylate experiments to children. Do not combine willow tea with anticoagulant drugs casually.</p></section><section class=\"entry-section\"><h3>Creation note</h3><p>The history of plant → medicine inspires gratitude for both gardens <strong>and</strong> careful pharmacy—not nostalgia that ignores safety.</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-mustard-plaster-historical-education-burn-risk-discourage-diy"] = { title: "25. Mustard Plaster Historical Education (burn risk — discourage DIY)", html: "<section class=\"entry-section\"><h3>Purpose (educational/historical)</h3><p>Explain mustard plasters as a <strong>historical</strong> counter-irritant folk practice—and why this curriculum <strong>discourages DIY</strong>.</p></section><section class=\"entry-section\"><h3>Historical sketch</h3><p>Ground mustard seed mixed with flour/water was applied externally in older nursing manuals to create heat/redness on the chest or back. Burns, blistering, and pigment changes were known risks even then.</p></section><section class=\"entry-section\"><h3>Why discourage DIY</h3><ul><li>Mustard’s pungent compounds can <strong>chemically irritate and burn</strong> skin—especially thin skin, children, elders, and people with sensation loss (e.g., some diabetes neuropathies).</li><li>Timing mistakes cause injury.</li><li>Respiratory illness needing oxygen, inhalers, or antibiotics is not solved by a chest burn.</li></ul></section><section class=\"entry-section\"><h3>If studying history only</h3><p>Read old texts as history; do <strong>not</strong> recreate on a person. Prefer modern clinical respiratory care and safe warmth (warm socks, humidified air per clinician advice).</p></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p>Do not place mustard preparations on children. Do not use if you cannot feel heat normally. Seek care for breathing distress.</p></section>" };
window.RECIPE_LOCALES["en"]["recipe-slippery-elm-inner-bark-gruel-tea-note-sustainability-first"] = { title: "26. Slippery Elm Inner-Bark Gruel / Tea Note (sustainability-first)", html: "<section class=\"entry-section\"><h3 data-i18n=\"purpose\">Purpose (educational/traditional)</h3><p>Mucilaginous inner-bark gruel/tea appears in North American folk tradition for soothing throat/digestive folklore—taught here with <strong>sustainability first</strong>.</p></section><section class=\"entry-section\"><h3>Sustainability teaching</h3><ul><li>Purchasing from <strong>reputable, sustainability-minded</strong> suppliers, <strong>or</strong></li><li>Using <strong>marshmallow leaf/root</strong> (<em>Althaea officinalis</em>) or <strong>plantain leaf</strong> as gentler stewardship alternatives for mucilage folklore when appropriate.</li></ul></section><section class=\"entry-section\"><h3>If using commercial slippery elm powder (adult food-like note)</h3><ul><li>Stir <strong>½–1 tsp</strong> powder into a little cold water to make a paste, then whisk into <strong>6–8 oz</strong> warm water or as a thin gruel; take slowly.</li><li>Optional: cinnamon for flavor (food).</li></ul></section><section class=\"entry-section\"><h3 data-i18n=\"storage\">Storage</h3><p>Keep powder dry/airtight; mix fresh.</p></section><section class=\"entry-section\"><h3 data-i18n=\"cautions\">Cautions</h3><p>May slow absorption of medicines—separate from pills by a couple of hours per pharmacist advice. Pregnancy: ask clinician. Texture can trigger gagging—go slowly. Not a substitute for evaluating GI bleeding, ulcers, or swallowing disorders.</p></section>" };
window.RECIPE_LOCALES["es"] = {};
window.RECIPE_LOCALES["es"]["primer-a"] = { title: "Guía práctica: preparaciones comunes y bases de seguridad", html: "<section class=\"entry-section\"><h3>Bases compartidas de seguridad (lea antes de cualquier receta)</h3><ol><li>1. XXBX Clean tools.**Lavar las manos, frascos, tapas, cucharas y tensores. Para extractos de alcohol o vinagre, comience con hierbas secas y tarros secos para reducir el riesgo de despojo.</li></ol><p>2.<strong>Etiqueta todo.</strong>Nombre, ingredientes, fecha hecha, alcohol % si es aplicable, y “solo externo” cuando es cierto. Los frascos sin etiqueta son cómo ocurren los accidentes. 3.<strong>Conoce tu planta.</strong>Usar hierbas secas de grado culinario o bien identificadas correctamente de proveedores respetables. Nunca forraje a menos que te entrenen; las apariencias pueden ser tóxicas. 4.<strong>Empieza bajo.</strong>Primer uso: pequeña cantidad, reloj para la alergia (inflamación, hinchazón, urticaria, dificultad para respirar → atención de emergencia). 5.<strong>Embarazo, enfermería, niños.</strong>Muchas hierbas son<strong>no</strong>apropiadas. Cuando una receta no dice explícitamente &quot;solo especias de cocina de nivel alimenticio&quot;, asuma<strong>preguntar a un médico primero</strong>. La miel es<strong>nunca</strong>para bebés menores de 1 año (riesgo de botulismo). Medicamentos 6.<strong>. Las hierbas</strong>pueden interactuar con las drogas.<strong>Nunca suspenda un medicamento recetados</strong>basado en este documento, ask a pharmacist or clinician. 7.<strong>Aceites esenciales (EO).</strong>No lo mismo que las hierbas secas en el té.<strong>No</strong>ingiere EOs ocasionalmente. Para uso tópico, diluye fuertemente en un aceite de portador y prueba de parche. Mantener alejado de los ojos, oídos interiores, mucosas, jaulas de mascotas y niños no supervisados. 8.<strong>Cuando descarte.</strong>Mold, de olores, molido que no debería estar allí, aceite nublado que estaba claro, o pasado una ventana de estante sensible → descarte. Cuando no esté seguro, échalo. 9.<strong>Cuándo ver a un médico.</strong>Fiebre alta, dificultad para respirar, dolor torácico, deshidratación severa, heces sangrientas, pérdida de peso sin explicación, heridas que empeoran, sospechan envenenamiento, crisis psiquiátrica, o cualquier síntoma que te asusta. Herbal cocina artesanal es<strong>no</strong>asistencia urgente.</p></section><section class=\"entry-section\"><h3>Infusión (tea - partes delicadas)</h3><p><strong>Qué es:</strong>Agua caliente derramada sobre hojas, flores o partes de plantas blandas; cubiertas empinadas.</p><p><strong>Método básico:</strong>Utilizar alrededor de<strong>1–2 cucharaditas de hierba seca</strong>(o un pequeño puñado de fresco) por<strong>8 oz (XXXXXX)</strong>Agua de techo cercano. Cubre 5-15 minutos. Strain.</p><p><strong>Seguridad:</strong>La cobertura mantiene aceites aromáticos en la taza. No asuma “natural = ilimitado”. Discuta el té sobrante después de un día en la nevera, o antes si huele.</p></section><section class=\"entry-section\"><h3>Decocción (simmer — partes más duras)</h3><p><strong>Qué es:</strong>Botas, cortezas, semillas o material maderado en agua.</p><p><strong>Método básico:</strong>Acerca<strong>1 cucharadita a 1 cucharada de material duro seco</strong>por taza de agua; cocer a fuego lento<strong>10–20 minutos</strong>cubierto; cepa.</p><p><strong>Seguridad:</strong>El calor más largo extrae más componentes, incluyendo amargos o irritantes. No decorar flores delicadas de la misma manera (a menudo se vuelven planas o duras).</p></section><section class=\"entry-section\"><h3>Tintura (extracto de alcohol)</h3><p><strong>Qué es:</strong>Material vegetal macerado en etanol (o etanol-agua) durante semanas, luego presionado/entrenado.</p><p><strong>Patrón de cocina educativa (adultos):</strong>Frecuentemente<strong>1 parte secó hierba por peso a 5 partes líquidas por volumen</strong>(un popular común “1:5”), utilizando<strong>40–60% de alcohol</strong>(80–120 espíritus de prueba de vodka) para muchas hierbas frondosas/aromáticas. Las raíces pueden necesitar una mayor prueba en la práctica profesional:<strong>esta imprenta no te entrena como farmacéutico.</strong></p><p><strong>Pasos bosquejo:</strong>Chop/crush herb → frasco → tapa completamente con alcohol → etiqueta → sacudir diariamente → esperar<strong>2–6 semanas</strong>→ cola → botella → botella en botellas de gotero → etiqueta con alcohol % y fecha.</p><p><strong>Seguridad:</strong>Mantente alejado de los niños. No para personas que deben evitar el alcohol. Embarazo: generalmente evitar las tinturas medicinales a menos que un médico dirija. La vida útil de una tintura bien hecha de alta prueba es a menudo<strong>años</strong>X si se almacena fresco / oscuro; descarte si nublado con crecimiento o olor extraño.<strong>Glycerites</strong>(extractos de glicerina) es un método diferente con una vida de estante más corta—estudio antes de sustituir.</p></section><section class=\"entry-section\"><h3>Syrup (cariño o azúcar + té fuerte/decocción)</h3><p><strong>Qué es:</strong>Un líquido endulzado y estabilizado de estante para un agradable sorbo (tradición alimentaria).</p><p><strong>Seguridad:</strong>Refrigerar jarabes caseros. La vida típica de la nevera casera se discute a menudo como<strong>semanas a unos pocos meses</strong>dependiendo de la relación de azúcar / dinero y la limpieza—<strong>cuando en duda, descarte</strong>.<strong>No hay miel para bebés menores de 1.</strong>Diabética: los jarabes son azúcar, secar un clínico. Los siropes son vehículos alimentarios****, no curas de enfermedad.</p></section><section class=\"entry-section\"><h3>Salve / ungüento (oil + beeswax)</h3><p><strong>Qué es:</strong>Aceite de infusión herbal engrosado con cera de abejas para la aplicación de la piel externa.</p><p><strong>Alfabetización de la relación básica:</strong>Muchos fabricantes de casas comienzan cerca de<strong>1 oz (28 g) abejaswax por 1 taza (240 mlX) aceite infundido</strong>, luego ajusta más firme/más suave. Derretir suavemente, verter en latas, fresco, etiqueta<strong>USO EXTERNO</strong>.</p><p>Seguridad<strong>: prueba de parche</strong>. Necesidades. La alergia a la abeja es posible. Mantén la tapa limpia.</p></section><section class=\"entry-section\"><h3>Poultice (herb fresca o humedecida en la piel)</h3><p><strong>Qué es:</strong>Planta húmeda triturada aplicada externamente, a menudo con un paño limpio.</p><p><strong>Seguridad:</strong>Contacto corto; reloj para la irritación. No estropee sobre la piel rota con plantas silvestres desconocidas. Quitar si la quema o la ampolla comienza.</p></section><section class=\"entry-section\"><h3>Vinagre (extractos acéticos / oxímeles)</h3><p><strong>Qué es:</strong>Herbs empinado en vinagre de manzana o vino; a veces se añade miel más tarde (tradición oximel).</p><p><strong>Seguridad:</strong>Usar vinagre de grado alimenticio (ácido acético del 95%). Evite tapas metálicas contactando vinagre a largo plazo (utilización de plástico o vidrio). Refrigerar si añade ajo fresco / cebolla o diluir con agua / miel. Los vinagres culinarios no son curas de plagas ni sustitutos desinfectantes para la infección clínica.</p></section>" };
window.RECIPE_LOCALES["es"]["primer-b"] = { title: "Guía en cuatro pasos para combinar hierbas con cuidado", html: "<p>Este es<strong>sinergía alfabetización</strong>, no una licencia para inventar “pilas milagrosas”.</p><section class=\"entry-section\"><h3>Paso 1 - Nombre de un objetivo tradicional claro</h3><p>Ejemplo: “después de mealizar el té”, no “desintoxicar tu hígado y matar patógenos”. Los mega-goales vagos invitan a apilar inseguro.</p></section><section class=\"entry-section\"><h3>Paso 2 - Elegir una sencilla hierba de hojalata que ya tolera</h3><p>Una hierba culinaria familiar o suave primero (peppermint, jengibre, manzanilla, bálsamo de limón). Confirme ninguna alergia y ningún conflicto con sus medicamentos.</p></section><section class=\"entry-section\"><h3>Paso 3 - Añadir a la mayoría de uno o dos socios de apoyo con un papel tradicional relacionado</h3><p>-<strong>Compañeros aromáticos</strong>(fennel con menta) para folclore digestivo. -<strong>Soothing mucilage partners</strong>(marshmallow leaf <em>instead of</em>X overharvested slippery elm cuando sea posible). -<strong>Flavor balanceadores</strong>(una pizca de canela en leche dorada)—el sabor es la administración, no una reclamación de drogas. Evite mezclar muchos activos fuertes (laxantes + sedantes + amargos estimulantes + EOs) “porque más es mejor”.</p></section><section class=\"entry-section\"><h3>Paso 4 - Revisar las advertencias como un conjunto, luego volver a evaluar</h3><p>Pregunta: ¿ embarazo? ¿Niños? ¿Más delgador de sangre? ¿Una cirugía pronto? ¿Sensibilidad al alcohol? integridad de la piel? Si alguna respuesta es incierta,<strong>simplifica la comida</strong>o<strong>pide a un clínico</strong>. Mantenga un diario de uso corto (cuánto, cuánto, cómo se sintió). Para si te sientes peor. Combinar hierbas hace<strong>no</strong>multiplica la santidad o garantiza el beneficio—la humildad es parte de la sabiduría (cf. el espíritu de la alabanza de los Proverbios del conocimiento con prudencia).</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-garden-settling-digestive-tea"] = { title: "1. Tea digestiva de asentamiento de jardín", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Un té aromático suave después de la comida en la larga tradición de la cocina de los digestivos de menta y semillas, folclore de confort, no un diagnóstico de &quot;IBS&quot; o enfermedad de úlcera.</p></section><section class=\"entry-section\"><h3>Ingredientes (1 taza)</h3><ul><li>1 tsp hoja de menta seca (<em>Mentha × piperita</em>)</li><li>1 tsp semilla triturada de hinojo (<em>Foeniculum vulgare</em>)</li><li>8 oz (240 ml) Agua de techo cercano</li><li>Opcional: rebanada fina jengibre fresco o algunas hojas de limón</li></ul></section><section class=\"entry-section\"><h3>Pasos</h3><ol><li>1. Combine hierbas en una taza o tetera.</li><li>2. Vierta agua caliente; cubre 10 minutos.</li><li>3. Strain; sierva caliente después de una comida.</li><li>4. No endulce fuertemente si está viendo azúcar en la sangre - miel opcional solo para adultos/ niños mayores por orientación clínica.</li></ol></section><section class=\"entry-section\"><h3>Almacenamiento</h3><p>Bebe fresca. Refrigerar las sobras hasta 24 horas; descartar si se apaga.</p></section><section class=\"entry-section\"><h3>Precauciones</h3><p>Peppermint puede empeorar el reflujo en algunas personas. El hinojo es generalmente culinario, pero las cantidades medicinales en el embarazo garantizan consejo clínico; raras alergias a las apiáceas existen. El aceite esencial de menta/fennel es<strong>no</strong>un sustituto de este té y es<strong>no</strong>para uso interno casual.</p></section><section class=\"entry-section\"><h3>Nota de creación</h3><p>Las hierbas aromáticas del jardín encajan en el patrón bíblico más grande de las plantas dadas para la alimentación y la vida cuidadosa (Génesis 1:29) sin inventar un “digestivo versículo milagroso”.</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-quiet-evening-lemon-balm-chamomile-cup"] = { title: "2. Copa silenciosa de limón y manzanilla", html: "<section class=\"entry-section\"><h3>Propósito (educativo / tradicional)</h3><p>Una suave taza de noche asociada al herbalismo popular con calma y asentamiento, no un tratamiento para los trastornos de ansiedad, la enfermedad del insomnio o la depresión.</p></section><section class=\"entry-section\"><h3>Ingredientes (1 taza)</h3><ul><li>1 tspBálsamo de limón seco (<em>Melissa officinalis</em>)</li><li>1 tsp flores secas de manzanilla alemana (<em>Matricaria chamomilla</em>)</li><li>8 oz (240 ml) Agua de techo cercano</li></ul></section><section class=\"entry-section\"><h3>Pasos</h3><ol><li>1. Coloque hierbas en una taza cubierta o una olla.</li><li>2. Ocultar 5-10 minutos (la manzanilla puede volver amarga si se sobresale para algunos paladares).</li><li>3. Strain; sierva por la noche lejos de las pantallas si te gusta un ritual de eólica.</li><li>4. Opcional goteo de miel adulto.</li></ol></section><section class=\"entry-section\"><h3>Almacenamiento</h3><p>Uso fresco preferido.</p><p>**Precauciones: XXBX La manzanilla está en la familia daisy, evite si tiene fuertes alergias de ragweed/chrysanthemum. El bálsamo de limón puede afectar teóricamente a los laboratorios/médicos de tiroides en uso concentrado, pregunta si tiene enfermedad tiroidea. Las pilas de sedating con medicamentos de sueño recetados necesitan consejo clínico. No es un sustituto de la atención de salud mental.</p><p>No se ven las gracias.</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-mullein-leaf-respiratory-steam-cup-tea"] = { title: "3. Taza de vapor respiratorio de hoja de gordolobo (té)", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Uso popular tradicional de la hoja de mulleina como un relajante aroma de té/té de temporada respiratoria— XXBX no**a neumonía, COVID, asma o tratamiento de tuberculosis.</p></section><section class=\"entry-section\"><h3>Ingredientes (1 taza)</h3><ul><li>hoja de mulleina seca 1–2 tsp (<em>Verbascum thapsus</em>), preferiblemente cortada y manchada</li><li>Agua 8–10 oz</li><li>Fichero fino o filtro de café (pelos multileinos pueden irritar gargantas)</li></ul></section><section class=\"entry-section\"><h3>Pasos</h3><ol><li>1. Vierta agua caliente sobre la hoja; cubrir 10-15 minutos.</li><li>2. Administrar el sistema de distribución de los productos para los productos.</li><li>3. Sip caliente, o inhale vapor cauteloso desde una distancia segura (sin quemaduras).</li><li>4. Límite al uso popular estacional corto a menos que un médico le recomiende lo contrario.</li></ol></section><section class=\"entry-section\"><h3>Almacenamiento</h3><p>Fresh.</p></section><section class=\"entry-section\"><h3>Precauciones</h3><p>No use mullein <em>seeds</em> o hoja borrosa sin filtrar casualmente. El asma y problemas respiratorios serios necesitan atención médica: el té no es un inhalador. Embarazo: pregunte primero. El folclore de humo existe históricamente;<strong>esta receta no anima a fumar hierbas.</strong></p></section>" };
window.RECIPE_LOCALES["es"]["recipe-fresh-ginger-root-comfort-tea"] = { title: "4. Tetera de confort de jengibre fresco", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Té clásico de cocina para días fríos y la educación folclore de insequibilidad estomacal – nivel de alimentos, no terapia antiemética recetada.</p></section><section class=\"entry-section\"><h3>Ingredientes (1 taza)</h3><ul><li>3-5 rebanadas finas raíz de jengibre fresca (~1–2 tsp rallado)</li><li>Agua 8–10 oz</li><li>Opcional: rebanada de limón; miel adulta al gusto</li></ul></section><section class=\"entry-section\"><h3>Pasos</h3><ol><li>1. Corta suavemente 10 minutos (estilo de decocción) o jengibre gris empinado en agua de cerca de techo 10 minutos. Estreno</li><li>2. ; agregue limón / dinero si se desea.</li><li>3. Sip caliente.</li></ol></section><section class=\"entry-section\"><h3>Almacenamiento</h3><p>Fresh; té sobrante refrigerado ~24 horas.</p></section><section class=\"entry-section\"><h3>Precauciones</h3><p>Ginger puede interactuar con los delgadores de sangre y puede molestar cálculos biliares o reflujo en algunas personas, asegúrate de un clínico si es relevante. Las megadosis medicinales en el embarazo pertenecen a la orientación clínica, no a los desafíos de Internet. El aceite esencial de jengibre es<strong>no</strong>para uso interno casual.</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-rosemary-folklore-clarity-tea-honest-limits"] = { title: "5. Rosemary Folklore Clarity Tea (límites de honor)", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Té romero culinario vinculado al folclore mediterráneo con “remembranza” y simbolismo de alerta:</p></section><section class=\"entry-section\"><h3>límite honesto</h3><p>no es una medicina probada de Alzheimer o IQ booster.</p></section><section class=\"entry-section\"><h3>Ingredientes (1 taza)</h3><ul><li>1 tspX hoja de rosas secas (<em>Salvia rosmarinus</em> / <em>Rosmarinus officinalis</em>X), desmoronada</li><li>8 oz Agua de techo cercano</li></ul></section><section class=\"entry-section\"><h3>Pasos</h3><p>horcampX</p><ol><li>1. Steep cubre 5–8 minutos (más amargo) Estreno</li><li>2. ; tomar ocasionalmente como un té de hierba culinario.</li><li>3. Pareja con un paseo y un buen sueño: Folklore sin pensamiento mágico.</li></ol></section><section class=\"entry-section\"><h3>Almacenamiento</h3><p>Fresh.</p></section><section class=\"entry-section\"><h3>Precauciones</h3><p>Evite grandes cantidades medicinales en el embarazo. Epilepsia o sensibilidad fuerte de los camphors: pregunte a un clínico. El aceite esencial de Rosemary<strong>**es concentrado, diluido aromático/tópico solamente,</strong>no**DIY oral. Las personas con presión arterial alta en medicamentos deben limpiar experimentos herbarios con un clínico.</p></section><section class=\"entry-section\"><h3>Nota de creación</h3><p>Rosemary es un regalo de cocinas mediterráneas; folclore de memoria es poesía cultural, no un reclamo clínico.</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-spring-nettle-leaf-food-like-tea"] = { title: "6. Hoja de Primavera Alimentaria-Me gusta Té", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Alimentar la infusión de la hoja de picadura seca — tradición de alimentos populares ricos en minerales, no una cura de purificador de sangre.</p></section><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>1–2 tspX hoja de nettle seco (<em>Urtica dioica</em>) por 8 oz agua</li></ul><p>(o 1 Tbsp por taza para una cerveza más fuerte como la comida algunas tradiciones prefieren)</p></section><section class=\"entry-section\"><h3>Pasos</h3><ol><li>1. Vierta agua de techo cerca de la hoja seca; cubre 10-15 minutos (algunos más empinados para un estilo de “nourishing”—flavor será más profundo/tierra).</li><li>2. Strain; beber como un té verde salado.</li><li>3. Opcional: pizca de menta para suavizar el sabor pastoso.</li></ol></section><section class=\"entry-section\"><h3>Almacenamiento</h3><p>Fresco o refrigerar hasta 24 horas.</p></section><section class=\"entry-section\"><h3>Precauciones</h3><p>Utilizar<strong>X secado</strong>o hoja cocida a fondo—fresh crudo nettles sting. Puede ser diurético; pregunte si usted toma presión arterial, diabetes, o medicamentos para el sangrado, o tiene enfermedad renal. Rara alergia posible. Forage only with expert ID (look-alikes exist in some regions).</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-kitchen-turmeric-golden-milk"] = { title: "7. Leche de Oro Turmérico de cocina", html: "<p>**Propósito (educativo/tradicional): XXBX Una bebida de leche picada caliente de la tradición de cocina inspirada en el sur de Asia—comfort comida con cúrcuma, no un “drogo antiinflamatorio” o protocolo de cáncer.</p><section class=\"entry-section\"><h3>Ingredientes (1 taza)</h3><ul><li>1 taza (240 ml) leche de elección ( leche de planta no deseada o sin soldadura)</li><li>½–1 tsp cúrcuma en polvo (<em>Curcuma longa</em>)</li><li>Pimienta negra de pellizco pequeño (folclore de emparejamiento tradicional para la cúrcuma culinaria)</li><li>Opcional: canela de 1⁄4 tsp; jengibre fresco de rodajas; miel de adulto para degustar</li></ul></section><section class=\"entry-section\"><h3>Pasos</h3><ol><li>1. La cúrcuma de batido (y especias opcional) en una roda de leche fría para hacer una pasta suave.</li><li>2. Calentar la leche restante suavemente—no abofetear.</li><li>3. Sumergir en la pasta; sumergir muy suavemente 3-5 minutos.</li><li>4. Endulzar ligeramente si es deseada; tomar caliente.</li></ol></section><section class=\"entry-section\"><h3>Almacenamiento</h3><p>Mejor fresco; refrigerar sobras ~24 horas; recalentar una vez.</p></section><section class=\"entry-section\"><h3>Precauciones</h3><p>Los suplementos de Turmeric/curcumin son<strong>no</strong>lo mismo que los polvos de cocina: los extractos de dosis altas pueden interactuar con los delgadores de sangre y afectar la enfermedad de la vesícula biliar. Embarazo: mantener hasta cantidades de alimentos a menos que el médico dirija. Ropa de estaño y mostradores.<strong>Nunca</strong>presenta leche dorada como receta anti-cáncer.</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-dark-berries-immune-season-elderberry-syrup-food-tradition"] = { title: "8. Dark Berries Immune-Season Elderberry Syrup (tradición alimentaria)", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Un jarabe cocido de elderberry en la tradición alimentaria fría de cocinas europeas—<strong>no</strong>una cura de gripe, tratamiento COVID o reemplazo de vacunas.</p></section><section class=\"entry-section\"><h3>Ingredientes (unos 2-3 tazas de jarabe, varía)</h3><ul><li>1 taza de elderberries negro seco (solo bayas maduras <em>Sambucus nigra</em>)**o XXBX ~2 tazas congeladas elderberries negro maduro</li><li>3 tazas de agua</li><li>1 palo de canela (opcional)</li><li>3-5 rebanadas de jengibre fresco (opcional)</li><li>1 taza de miel (o al gusto; añadir<strong>a fuego</strong>)</li></ul></section><section class=\"entry-section\"><h3>Pasos</h3><ol><li>1. Las bayas de inmersión (y especias opcionales) en agua alrededor de 30 a 45 minutos hasta que el líquido disminuye aproximadamente en un tercio a una mitad.</li><li>2. Mash ligeramente; colar a través de una malla fina o un paño (evitar la búsqueda en los ojos).</li><li>3. Cool hasta caliente, no caliente; revuelva en miel.</li><li>4. Botella en vidrio limpio; etiqueta y fecha; refrigerar.</li></ol></section><section class=\"entry-section\"><h3>Almacenamiento</h3><p>Refrigerate; la enseñanza típica de la casa a menudo tiene como objetivo utilizar dentro de<strong>1–3 meses</strong>—descarte en molde, fermento o olor.</p></section><section class=\"entry-section\"><h3>Precauciones</h3><p>Utilice solo<strong>madura cocinado</strong>negro elderberries de fuentes de confianza <em>S. nigra</em>. Las bayas crudas, hojas, corteza y otras partes <em>Sambucus</em> pueden causar náuseas. Enfermedad autoinmune o medicamentos inmunosupresores: pregunte a un médico antes del uso folclórico “inmune”.<strong>No hay miel para bebés menores de 1.</strong>Diabetes: la carga de azúcar importa. Esta es la educación de la tradición alimentaria, no una reclamación antiviral de drogas.</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-garlic-in-honey-folk-preserve-food"] = { title: "9. Ajo-en-Honey Folk Preserve (comida)", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Coágulos de ajo pelados preservados en la miel como condimento de alimentos folclóricos – interés escolar, no un reemplazo antibiótico.</p></section><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>Coágulos de ajo pelados para llenar un pequeño frasco limpio (alrededor de 1 taza de coágulos)</li><li>Suficiente miel cruda o pasteurizada para cubrir completamente</li></ul></section><section class=\"entry-section\"><h3>Pasos</h3><ol><li>1. Usar coágulos secos, sin mancha; triturador opcional de luz.</li><li>2. Coloque en frasco; cubra completamente con miel; suelte burbujas de aire con un palillo limpio.</li><li>3. Lid suelto al principio si el ajo muy fresco libera gases; luego sellar.</li><li>4. Almacene fresco / oscuro; los coágulos se suavizan durante días a semanas. Usar como goteo/condición de alimentos.</li></ol></section><section class=\"entry-section\"><h3>Almacenamiento</h3><p>Cool despensa o frigorífico; observe la espuma inusual o molde desechable si es sospechoso. Algunos prefieren la refrigeración con precaución.</p></section><section class=\"entry-section\"><h3>Precauciones</h3><p>Botulism risk conversations exist around low-acid ajo-in-oil; miel-garlic es una matriz diferente pero todavía requiere limpieza y sentido común:<strong>no dan a los bebés.</strong>El ajo puede aumentar la tendencia sangrante e interactuar con los medicamentos contra el VIH y los anticoagulantes, si es relevante. Uso de alimentos ≠ tratar la infección en lugar de atención médica.</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-honey-onion-household-cough-syrup-food-tradition"] = { title: "10. Miel-Onion Household Cough Syrup (tradicionalidad alimentaria)", html: "<p>XXBX Propósito (educativo/tradicional):**Viejo hogar dulce cebolla-y-cariño jarabe para calmante folclore de dolor de garganta - tradición alimentaria, no cuidado de neumonía.</p><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>1 cebolla media, rebanada finamente</li><li>Suficiente miel para cubrir rebanadas en un frasco (alrededor de 1⁄2–1 taza)</li></ul></section><section class=\"entry-section\"><h3>Pasos</h3><ol><li>1. Cebolla de cebolla en un frasco limpio; cubre con miel.</li><li>2. Dejar sentarse de 2 a 4 horas (o de la noche a la noche en el refrigerador) hasta formas líquidas de jarabe.</li><li>3. Estrecho líquido en una botella limpia; descarte sólidos o utilice en la cocina si lo desea.</li><li>4. Adultos: pequeños cucharadas como jarabe de comida relajante. Niños mayores: solo con el juicio clínico/parente;<strong>nunca menor de 1 (cariño).</strong></li></ol></section><section class=\"entry-section\"><h3>Almacenamiento</h3><p>Refrigerate; use dentro de ~1 semana; descarte si apagado.</p></section><section class=\"entry-section\"><h3>Precauciones</h3><p>Tos persistente, fiebre alta o dificultad para respirar → clínico. Cariño no para bebés. La cebolla puede molestar al reflujo.</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-sunshine-calendula-infused-oil"] = { title: "11. Sunshine Calendula Aceite Infundido", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Aceite infundido con pétalos de caléndula para folclore externo de placer de la piel: parches secos y chapped-skin craft, no tratamiento de infección.</p></section><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>1 taza de pétalos de caléndula secados (<em>Calendula officinalis</em>)</li><li>11⁄4–11⁄2 tazas de aceite de oliva (con una cubierta de aceite seco de ~1 pulgada)</li></ul></section><section class=\"entry-section\"><h3>Pasos (método caliente de alta velocidad)</h3><ol><li>1. Place pétalos completamente secos.</li><li>2. Establece un frasco en un baño de agua caliente o un yogurt-maker-type warmth<strong>bien debajo del calor de freír</strong>durante varias horas, o el método popular soleado-ventana durante 1–2 semanas (evitar sobrecalentamiento/spoiling).</li><li>3. Agita suavemente cuando recuerdas.</li><li>4. Strain a través de tela; botella; etiqueta<strong>USO EXTERNO</strong>con fecha.</li></ol></section><section class=\"entry-section\"><h3>Almacenamiento</h3><p>Cool/dark; a menudo meses si la hierba seca y el proceso limpio – descartar si es nublado, moho o rócido.</p></section><section class=\"entry-section\"><h3>Precauciones</h3><p>Alergía Margarita-familia posible. Externo solo. No use en los ojos. Las heridas profundas o infectadas necesitan atención médica.</p><p>**Nota de creación: XXBX Los pétalos Marigold-bright son una humilde misericordia de jardín para manos que trabajan en el suelo.</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-calendula-garden-salve"] = { title: "12. Ungüento de caléndula del jardín", html: "<p>**Propósito (educativo/tradicional): XXBX Beeswax-thickened calendula oil for external chapped-skin craft.</p><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>1 taza de caléndula aceite infundido (Receta 11)</li><li>~1 oz (X28 g) abejaswax (pastilles o grated)—ajuste para el set más firme/más suave</li><li>Opcional: 1–2 tsp vitamina E aceite como medicamento antioxidante vida popular</li></ul></section><section class=\"entry-section\"><h3>Pasos</h3><ol><li>1. Aceite suavemente fundido + cera de abejas en una caldera doble hasta que se combina.</li><li>2. Quitar del calor; vitamina E.</li><li>3. Pour opcional en latas limpias; fresco sin perturbar.</li><li>4. Label<strong>SOLO USO EXTERNO</strong>, fecha, ingredientes.</li></ol></section><section class=\"entry-section\"><h3>Almacenamiento</h3><p>Cool/dark; a menudo muchos meses; descartar si el olor se vuelve rancio.</p></section><section class=\"entry-section\"><h3>Precauciones</h3><p>Prueba de parche. Alergía Beeswax posible. No para heridas profundas, mordeduras de animales o uso de los ojos.</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-aloe-leaf-gel-external-cool-note"] = { title: "13. Aloe Leaf Gel — Nota fresca externa", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>gel fresco de hoja interna utilizado externamente en muchas culturas para calmar la piel quemada o irritada — nota externa educativa, no el cuidado de unidad de quemadura.</p></section><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>1 hoja exterior madura de <em>Aloe vera</em> (planta de grado alimenticio-cosmético, plaguicida-aware)</li></ul><p>XXBX Pasos:**</p><ol><li>1. Hoja de enjuague; puntas de trim.</li><li>2. Fillet para exponer el gel interior claro; evitar el látex amarillo justo debajo de la piel cuando sea posible (latex es un laxante estimulante y puede irritar). Gel transparente</li><li>3. ; mezcla breve opcional para suavidad.</li><li>4. Aplica una capa fina<strong>externamente</strong>a la piel intacta encajada al sol; refrigera el gel sobrante en un frasco limpio y utiliza dentro de unos días.</li></ol></section><section class=\"entry-section\"><h3>Almacenamiento</h3><p>Nevera; pocos días; descarte si aparece un despilfarro rosa/rojo.</p></section><section class=\"entry-section\"><h3>Precauciones</h3><p>Prueba de parche. No use en quemaduras severas (busca atención médica). Latex orally is<strong>not</strong>recommended here—stimulant laxative risks, pregnancy contraindication in traditional teaching, and regulatory safety concerns. Los aceites esenciales no pertenecen a este gel para experimentos casuales “más fuertes”.</p></section><section class=\"entry-section\"><h3>Nota de Escritura</h3><p>Biblical “aloes” en algunos versículos probablemente se refieren a aromática de tipo águila fragante,<strong>no</strong>idéntico al gel <em>Aloe vera</em>X moderno, cada una de las distinciones honestamente (ver monografía Aloes).</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-plantain-leaf-field-poultice"] = { title: "14. Cataplasma de campo de hoja de llantén", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Poultice exterior folclórico clásico de plantaina de hoja ancha o ribwort para rasguños menores y folclore de insectos-primer-ayuda educación adyacente, no cuidado de ER.</p></section><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>Varias hojas limpias <em>Plantago major</em> o <em>P. lanceolata</em> (identificación positiva requerida)</li><li>Agua limpia; tela limpia</li></ul></section><section class=\"entry-section\"><h3>Pasos</h3><ol><li>1. Lavar las hojas bien.</li><li>2. Cierre brevemente<strong>solo si</strong>usted confía en el ID de la planta y su boca es saludable—o aplastado con una cuchara limpia para herir y humedecer.</li><li>3. Aplicar a áreas superficiales intactas o muy menores; cubrir ligeramente con tela 10-20 minutos.</li><li>4. Quitar; lavar la piel; observar la irritación.</li></ol><p>Se trata de un proyecto de ley .</p></section><section class=\"entry-section\"><h3>Precauciones</h3><p>El ID de planta incorrecta es peligroso, no improvisar si no está seguro. Punturas profundas, signos de infección, picaduras de garrapata de preocupación, o picaduras de animales → clínico. No use poultices de corte bucal en personas inmunocompromisadas sin consejo clínico.</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-comfrey-leaf-external-only-salve-note"] = { title: "15. Comfrey Leaf Externamente Salve Note", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Entrada de enseñanza para<strong>externa-solo</strong>comfrey craft literacy—y una línea dura contra el uso interno.</p></section><section class=\"entry-section\"><h3>Ingredientes (modelo externo educativo)</h3><ul><li>1 taza de hoja de comfrey seca (<em>Symphytum officinale</em>) infundida en aceite de oliva (método como aceite de caléndula)</li><li>Beeswax para salve la consistencia (~1 oz por taza de aceite como punto de partida)</li></ul></section><section class=\"entry-section\"><h3>Pasos</h3><ol><li>1. Infuse</li></ol></section><section class=\"entry-section\"><h3>hoja XXBX aceite con hierba seca y proceso limpio; cepa.\n2. Hacer salve como en la Receta 12.\n3. Label boldly</h3><p>SOLO USO EXTERNO — NO INGEST**.</p><ol><li>4. Use escasamente en la piel no rota para la educación tradicional de bruise/sprain folclore.</li></ol></section><section class=\"entry-section\"><h3>Almacenamiento</h3><p>Cool/dark; descartar si rancid.</p></section><section class=\"entry-section\"><h3>Precauciones (críticas)</h3><p>Comfrey contiene alcaloides de la pirrolizidina XXBX ligados a la toxicidad hepática grave cuando se toma internamente.<strong>Sin té combinado, sin batidos combinados, sin tinturas internas en este currículo.</strong>Evite las heridas profundas o la piel rota donde la absorción aumenta. Evite en el embarazo, la lactancia y en los niños. Preferir los productos profesionales reducidos por PA si un clínico alguna vez recomienda un tipo combinado tópico, y todavía tratar como enseñanza externa.</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-lavender-linen-sachet-dilute-topical-note"] = { title: "16. Lavender Linen Sachet \" Dilute Topical Note", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Lavanda seca para fragancia de lino y aroma tópico <em>highly diluted</em>, no medicina oral esencial-oil.</p></section><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>1⁄2–1 taza de cogollos de lavanda seca (<em>Lavandula angustifolia</em>) para cuchillas</li><li>Para diluir tópico (adultos): 1 gota de aceite esencial de lavanda 1 tsp (5 ml) aceite portador (aproximado<strong>1%</strong>ballpark)—o saltar completamente EO y frotar los cogollos secos en las manos para el olor</li></ul></section><section class=\"entry-section\"><h3>Pasos (sachet)</h3><ol><li>1. Llenar pequeñas bolsas de tela con brotes secos; corbata cerrada.</li><li>2. Lugar en cajón o debajo de almohada (la preferencia del aroma varía).</li><li>3. Refresca cuando el olor se desvanece.</li></ol><p>Pasos</p></section><section class=\"entry-section\"><h3>(diluido opcional tópico)</h3><ol><li>1. Mezcla EO en el portaaviones; prueba de parche brazo interno 24 horas.</li><li>2. Dab en la piel de punta de pulso si es tolerada.</li><li>3. Lavar las manos después; alejarse de los ojos.</li></ol></section><section class=\"entry-section\"><h3>Almacenamiento</h3><p>Hojas secas en el aire y el enfriamiento; botellas EO oscuras/friol, impermeables.</p></section><section class=\"entry-section\"><h3>Precauciones</h3><p><strong>No ingerir el aceite esencial de lavanda casualmente.</strong>Algunas personas obtienen dolores de cabeza por fuerte olor. Las mascotas (especialmente los gatos) pueden ser sensibles a los OE-ventilados; no se aplican a los animales sin guía veterinaria. Niños: se adhieren a las manchas secas a menos que un médico le aconseje.</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-rosemary-garden-hair-rinse"] = { title: "17. Enjuague capilar de romero del jardín", html: "<p>Un folclore de frescura, no una cura de alopecia médica.</p><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>2 Tbsp rosario seco</li><li>2 tazas de agua</li><li>Opcional: vinagre ácido manzana 1 Tbsp en el enjuague refrigerado (tradición popular del cuero cabelludo)</li></ul></section><section class=\"entry-section\"><h3>Pasos</h3><ol><li>1. Romero de inmersión en agua de 10 a 15 minutos; fresco; cola bien.</li><li>2. Después del champú normal/condición, verter el enjuague sobre el cabello / cuero cabelludo.</li><li>3. No enjuague a menos que lo desee; estilo como de costumbre.</li><li>4. Use ocasionalmente; descontinúe si la irritación.</li></ol></section><section class=\"entry-section\"><h3>Almacenamiento</h3><p>Enjuague el té refrigerado hasta 3 días; descarte si nublado/apagado.</p></section><section class=\"entry-section\"><h3>Precauciones</h3><p>Mantener fuera de los ojos. Las condiciones del cuero cabelludo (psoriasis, infección) necesitan atención clínica. Los enjuagues EO son una artesanía diferente, de mayor riesgo, esta receta utiliza té, no aceite esencial recto.</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-four-aromatics-historical-vinegar-culinary-cleaning-adjacent"] = { title: "18. Cuatro Aromáticos Vinagre Histórico (culinario / limpieza-adyacente)", html: "<section class=\"entry-section\"><h3>Propósito (educativo / tradicional)</h3><p>Un vinagre aromático original en el <em>spirit</em> de folclore “cuatro ladrones” de principios-moderno—fabricación de historia<strong>X + uso culinario/limpieza-adyacente del hogar</strong>. Es<strong>no</strong>una cura de plagas, medicamentos antivirales, o sustituto de vacunas, antibióticos o medidas de salud pública.</p></section><section class=\"entry-section\"><h3>Honestidad histórica</h3><p>Historias de ladrones que usan vinagre a base de hierbas durante años de peste son más tarde folclore capas en tradiciones aromáticas reales. Recetas variadas ampliamente; los productos de marca moderna son propietarios. Esta fórmula es una<strong>reconstrucción educativa fresca</strong>, no una copia de la mezcla de cualquier libro.</p></section><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>2 tazas (480 ml) vinagre crudo de ácido manzana (~5% acidez)</li><li>1 Tbsp rosario seco</li><li>1 Tbsp Sage seco</li><li>1 Tbsp brotes de lavanda seca</li><li>1 Tbsp</li><li>2-3 dientes de ajo pelado (opcional; aumenta la precaución de despojo)</li><li>1 palo de canela pequeña (opcional)</li></ul></section><section class=\"entry-section\"><h3>Pasos</h3><ol><li>1. Colocar hierbas (y ajo opcional/cinnamón) en un frasco de vidrio limpio.</li><li>2. Cubrir con vinagre por lo menos 1 pulgada; sellar con tapa no metatal-contacto.</li><li>3. Guardar 2-4 semanas, temblar ocasionalmente; mantener la calma / oscuro.</li><li>4. Strain; botella; etiqueta “el vinagre aromático cultivar – no un medicamento”.</li></ol><p>Infórmese en el caso de que el molde aparezca.</p></section><section class=\"entry-section\"><h3>Usos educativos sugeridos</h3><p>Aderezos salados (diluidos con aceite); como contraparador de cocina<strong>después de</strong>limpieza adecuada para el aroma (el vinagre no es una reclamación desinfectante hospitalaria). Hacer<strong>no</strong>beber como una “tónica de plaga desintoxicante”.</p></section><section class=\"entry-section\"><h3>Precauciones</h3><p>Toallero externo: diluir; no empapar la piel. Culinario: ajo-vinegar no para bebés; interacciones como con ajo. Embarazo: hierbas a nivel de alimentos generalmente difieren de los vinagres medicinales que ayudan, si no están seguros.</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-simple-kitchen-digestive-bitters-aromatic-vinegar-style"] = { title: "19. Ficheros digestivos de cocina simple (estilo de vinagre aromático)", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Un suave vinagre amargo aromático para folclore antes de la comida (cuo apetitivo/digestivo)—no un protocolo hepático “limpio” o parasito.</p></section><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>11⁄2 tazas de vinagre de ácido manzana</li><li>1 Tbsp de cáscara de naranja seca (grado alimentos)</li><li>1 tsp raíz gentiana<strong>o</strong>omit gentian y utilizar 1 tsp raíz de diente seca para una versión de enseñanza más suave</li><li>1 tsp semilla de hinojo</li><li>1⁄2 tsp jengibre, secado, o algunas rebanadas frescas</li><li>Opcional: miel 2–4 Tbsp después de colar (estilo oximel)</li></ul></section><section class=\"entry-section\"><h3>Pasos</h3><ol><li>1. Combine botánicos en un frasco; cubrir con vinagre.</li><li>2. Guardar 2-3 semanas; sacudar de vez en cuando.</li><li>3. Strain; miel opcional mientras el líquido no está caliente.</li><li>4. Adultos: tradicionalmente un sabor**pequeño</li></ol></section><section class=\"entry-section\"><h3>(por ejemplo, 1 cucharadita en un poco de agua) antes de las comidas</h3><p>parar si te molesta.**</p></section><section class=\"entry-section\"><h3>Almacenamiento</h3><p>Cool/dark; meses típicos para extractos de vinagre; descarte si se estropea.</p></section><section class=\"entry-section\"><h3>Precauciones</h3><p>Las amargas fuertes pueden agravar úlceras, reflujo o náuseas. Gentian es intensamente amargo, omitir si es demasiado duro. Embarazo: evite los amargos medicinales a menos que el médico dirija. No para los niños como un “experimento tónico”. Esto no es terapia antibiótica.</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-levant-table-za-atar-style-herb-blend"] = { title: "20. Mezcla de hierbas estilo za’atar de mesa levantina", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Mezcla culinaria de sésamo-herb-spice inspirada en las tradiciones de mesa Levantine: alegría alimentaria, no una fórmula médica. Las recetas regionales de za’atar varían; esta es una mezcla original de enseñanza de cocina**, no una copia de marca.</p></section><section class=\"entry-section\"><h3>Ingredientes (pequeño frasco)</h3><ul><li>3 Tbsp tomillo seco (o una mezcla de tomillo + orégano)</li><li>1 Tbsp marjoram seco o orégano adicional</li><li>2 Tbsp semillas tostadas de sésamo</li><li>1–2 tsp sumac</li><li>1⁄2–1 tsp sal fina (opcional)</li><li>Comin de tierra asado de pellizco opcional</li></ul></section><section class=\"entry-section\"><h3>Pasos</h3><ol><li>1. Tostadas ligeramente semillas de sésamo hasta fragante; fresco.</li><li>2. Hierbas crudas; mezclar con sumac, sésamo y sal/cumin opcional.</li><li>3. Pruebe; ajuste la tardanza (suma) y la sal.</li><li>4. Servir con aceite de oliva y pan como alimento.</li></ol><p><strong>Almacenamiento: frasco</strong>Airtight, fresco / oscuro, ~1–3 meses para el mejor aroma.</p></section><section class=\"entry-section\"><h3>Precauciones</h3><p>Alivios alimenticios (sésamo). Dietas sensibles a la sal: omitir sal. Culinario solo.</p><p>**Creación / nota de cultura: XXBXCompartir el pan y el aceite es similar a temas de hospitalidad antiguos en el mundo de las Escrituras, sin reclamar este frasco de especias exacto aparece en un versículo.</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-avicenna-inspired-rosewater-educational-note"] = { title: "21. Nota educativa de agua de rosas inspirada en Avicena", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Alfabetización histórica alrededor del agua de rosa (<em>maa’ ward</em>) en el patrimonio médico y culinario persa/islámica asociado con figuras como Ibn Sina (Avicenna)—<strong>X Educación aromática/culinaria</strong>, no una reconstrucción de un protocolo moderno de marca de hidrosol con copyright.</p></section><section class=\"entry-section\"><h3>Uncertainty</h3><p>La verdadera producción de hidrosol utiliza equipo de destilación de vapor y conocimientos de rendimiento/seguridad. Los métodos de “petalos de rosa de martillo y botella” producen un<strong>frágil agua aromática</strong>que estropea rápidamente y es<strong>no</strong>idéntico al agua de rosa destilada por vapor comercial.</p></section><section class=\"entry-section\"><h3>Agua aromática casera suave (escuela corta)</h3><ul><li>1–2 tazas de pétalos de rosa fragante sin pesticidas (<em>Rosa × damascena</em> o rosas culinarias, no rosas de plaguicidas floristas)</li><li>Agua solo para cubrir</li></ul></section><section class=\"entry-section\"><h3>Pasos</h3><ol><li>1. Sumergir muy suavemente, cubiertos, 15-20 minutos; no es duro-boil a barro.</li><li>2. Cool; cola; refrigerar inmediatamente en vidrio limpio.</li><li>3. Uso dentro de<strong>varios días</strong>como un enjuague aromático para cara/skin<strong>prueba parche primero</strong>, o una gota en postres adultos—preferir agua de rosa comercial a base de alimentos para la confiabilidad de la cocina.</li><li>4. Discutan en la nube o el malcriado.</li></ol></section><section class=\"entry-section\"><h3>Precauciones</h3><p>El riesgo de esponja es alto —cuando no está seguro, compre agua de rosa de calidad alimentaria. Evitar los ojos. El aceite esencial de la rosa es costoso y concentrado—<strong>no</strong>para uso interno casual. Embarazo: el agua de rosa culinaria a nivel alimentario difiere de las reivindicaciones medicinales, manteniéndose humilde.</p></section><section class=\"entry-section\"><h3>Nota histórica</h3><p>Celebra la historia intelectual de la destilación sin pretender que una cacerola es igual a un salón medieval.</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-kyphi-inspired-temple-aromatics-incense-note"] = { title: "22. Nota de incienso aromático de templo inspirado en kyphi", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Nota de incienso solo aromático inspirada en tradiciones egipcias <em>kyphi</em> y botánicos inciensos bíblicos (franquiceno, mirra y aromática hisopo-adyacente)— Olfato<strong>X e historia</strong>, no medicina pulmonar o protocolo médico místico.</p></section><section class=\"entry-section\"><h3>Uncertainty</h3><p>Las recetas antiguas de kyphi eran complejas (vino, miel, resinas, muchos aromáticos) y variadas por texto fuente. Este es un<strong>mezcla de estudio aromático moderno simplificado</strong>, no una fórmula precisa del museo y no copiada de un libro ritual copyrighted.</p></section><section class=\"entry-section\"><h3>Mezcla de estudio de resina simple (ventilado)</h3><ul><li>1 tsp lágrimas de incienso</li><li>1⁄2 tsp lágrimas de mirra</li><li>Opcional: pizca de hisopo seco o corteza de canela para la comparación de aromas educativos</li><li>Disco de carbón diseñado para incienso<strong>o</strong>observar resinas en un calentador hecho a propósito por instrucciones del dispositivo</li></ul></section><section class=\"entry-section\"><h3>Pasos</h3><ol><li>1. Ventanas abiertas; eliminar niños/pechos con sensibilidad de humo de la habitación.</li><li>2. Carbón ligero cuidadosamente en un quemador a prueba de fuego; espere hasta que se amontone encima—o use un calentador de resina eléctrica.</li><li>3. Coloque una cantidad<strong>diminuta</strong>de resina; observe el aroma brevemente.</li><li>4. Extinguir con seguridad; nunca dejar incienso incendiario inadvertido.</li></ol></section><section class=\"entry-section\"><h3>Almacenamiento</h3><p>Resins en frascos herméticos, frescos / secos.</p></section><section class=\"entry-section\"><h3>Precauciones</h3><p><strong>El humo irrita los pulmones.</strong>Evite con asma, bebés, problemas de exposición al humo del embarazo o alarmas de humo/riesgo de fuego. Esta es la terapia antimicrobiana XXBX no**, la liberación “protocolo” o un sustituto de la pastoral. El incienso bíblico tiene historia de adoración (por ejemplo, incienso franco en Mateo 2:11 como regalo; leyes de incienso del templo en Éxodo) — cada veneración y seguridad juntos, no el misticismo médico DIY.</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-olive-oil-anointing-pastoral-note-james-5"] = { title: "23. Olive Oil Anointing Pastoral Note (Santiago 5)", html: "<p><strong>Propósito (educativo/pastoral): XXBX Aceite de oliva como práctica de fe</strong>XXBX de oración y cuidado en comunidades cristianas, siguiendo el patrón pastoral de Santiago 5—<strong>no</strong>un protocolo médico, farmacéutico o cura física garantizada.</p><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>Una pequeña cantidad de aceite de oliva puro en un frasco limpio reservado para el uso de la oración</li></ul></section><section class=\"entry-section\"><h3>Pasos pastorales (descripción educativa, no un mandato litúrgico)</h3><ol><li>1. Los ancianos/pasadores y la persona enferma se reúnen en oración mientras la comunidad discierne.</li><li>2. El aceite se puede aplicar ligeramente (cabeza o cabeza)<strong>con el consentimiento</strong>, mientras reza.</li><li>3. Busque atención médica en paralelo: la fe y la medicina no son enemigos.</li><li>4. Mantenga el aceite limpio; no &quot;prescriba&quot; hierbas bajo el nombre de la unción.</li></ol></section><section class=\"entry-section\"><h3>Almacenamiento</h3><p>Aceite de oliva culinario fresco, fresco / oscuro; reemplazar si rancio.</p></section><section class=\"entry-section\"><h3>Precauciones</h3><p>Este es<strong>Simbolismo sacramental/pastoral y oración</strong>, no un reclamo de tratamiento. No demore la atención de emergencia. La alergia a la piel al aceite de oliva es poco común pero posible. No agregue aceites esenciales aleatorios a la unción “supercarga” que confunde categorías y puede dañar la piel.</p></section><section class=\"entry-section\"><h3>Nota de escritura (honesta)</h3><p>¿Hay alguien entre ustedes enfermo? Que llamen a los ancianos de la iglesia para orar sobre ellos y ungirlos con aceite en el nombre del Señor” (Santiago 5:14). El pasaje centra la oración<strong>y la comunidad</strong>, no una fórmula de farmacia.</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-willow-bark-caution-prefer-clinician-otc-aspirin-literacy"] = { title: "24. Precaución de Barco Willow — Preferir Literatura Clínica / OTC Aspirina", html: "<section class=\"entry-section\"><h3>Propósito (educativo)</h3><p>Enséñale por qué este currículo**no da una receta de dosificación de té DIY willow-bark para dolor/fever.</p></section><section class=\"entry-section\"><h3>¿Por qué precaución en lugar de una receta</h3><ul><li>La corteza de sauce (<em>Salix</em> spp.) contiene compuestos relacionados con salicilatos históricamente vinculados a la historia de la aspirina —pero la<strong>concentración varía</strong>según especie, cosecha y preparación.</li><li>La aspirina y los salicilatos tienen clara toxicidad<strong>, hemorragia, síndrome de Reye (niños/muertos con enfermedad viral), embarazo, úlcera e interacción de drogas</strong>.</li><li>La medición del té de corteza en casa es un pobre sustituto de los formularios de dosis etiquetados.</li></ul></section><section class=\"entry-section\"><h3>Preferencia</h3><ul><li>Orientación clínica para el dolor / fiebre.</li><li>Labeled OTC aspirin<strong>solo</strong>cuando sea apropiado para la persona (edad, estado de embarazo, riesgo de sangrado, enfermedad viral en la juventud, etc.)- etiquetas de lectura; pregunte a un farmacéutico.</li><li>Medidas antidrogas de confort (hidración, descanso) cuando es adecuado.</li></ul></section><section class=\"entry-section\"><h3>No</h3><p>Boil sauce aleatorio para “aspiración natural”. No le des experimentos salicilatos a los niños. No combine té sauce con medicamentos anticoagulantes casualmente.</p></section><section class=\"entry-section\"><h3>Nota de creación</h3><p>La historia de la planta → la medicina inspira gratitud por los jardines<strong>y</strong>farmacia cuidadosa—no nostalgia que ignora la seguridad.</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-mustard-plaster-historical-education-burn-risk-discourage-diy"] = { title: "25. Mustard Plaster Historical Education (riesgo a quemar - desaliento DIY)", html: "<section class=\"entry-section\"><h3>Propósito (educativo/histórico)</h3><p>Explicar los yesos de mostaza como una práctica folklórica<strong>histórica</strong>, y por qué este curriculum<strong>desalienta el DIY</strong>.</p></section><section class=\"entry-section\"><h3>Esbozo histórico</h3><p>La semilla de mostaza molida mezclada con harina/agua se aplicó externamente en manuales de enfermería antiguos para crear calor/rojo en el pecho o la espalda. Los quemaduras, ampollas y cambios de pigmento eran riesgos conocidos incluso entonces.</p></section><section class=\"entry-section\"><h3>¿Por qué desalentar DIY</h3><ul><li>Los compuestos pungentes de mostaza pueden irritar y quemar químicamente la piel**, especialmente la piel delgada, los niños, los ancianos y las personas con pérdida de sensación (por ejemplo, algunas neuropatías de diabetes).</li><li>Los errores de tiempo causan lesiones.</li><li>La enfermedad respiratoria que necesita oxígeno, inhaladores o antibióticos no se resuelve mediante una quemadura de pecho.</li></ul></section><section class=\"entry-section\"><h3>Si estudias historia solamente</h3><p>Lee textos antiguos como historia; haz<strong>no</strong>recrea en una persona. Preferir atención respiratoria clínica moderna y calidez segura (calcetines calientes, aire humidificado por consejo clínico).</p></section><section class=\"entry-section\"><h3>Precauciones</h3><p>No coloque los preparativos de mostaza en niños. No use si no puede sentir calor normalmente. Busca atención para respirar angustia.</p></section>" };
window.RECIPE_LOCALES["es"]["recipe-slippery-elm-inner-bark-gruel-tea-note-sustainability-first"] = { title: "26. Nota de gacha/té de corteza interna de olmo resbaladizo (sostenibilidad primero)", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Mucilaginous interior-bark gruel/tea aparece en la tradición popular de América del Norte para calmar la garganta / folclore digestivo—traído aquí con<strong>sostenibilidad primero</strong>X.</p></section><section class=\"entry-section\"><h3>Enseñanza de sostenibilidad</h3><p>Las poblaciones resbaladizas silvestres (<em>Ulmus rubra</em>) han enfrentado enfermedades y presión de cosecha. Preferencia:</p><ul><li>Compras de proveedores<strong>reputables, de mentalidad sostenible,</strong>o**</li><li>Utilizando la hoja de malvavisco<strong>X (<em>Althaea officinalis</em>X) o la hoja de plantación</strong>como alternativas de administración más suaves para el folclore de mucilación cuando sea apropiado.</li></ul></section><section class=\"entry-section\"><h3>Si se utiliza el polvo de elm resbaladizo comercial (nota similar a la comida)</h3><ul><li>Stir<strong>1⁄2–1 tsp</strong>polvo en un poco de agua fría para hacer una pasta, luego batir en<strong>6–8 oz</strong>agua caliente o como un gruel delgado; tomar lentamente.</li><li>Opcional: canela para sabor (alimentos).</li></ul></section><section class=\"entry-section\"><h3>Almacenamiento</h3><p>Mantener polvo seco/auricular; mezclar fresco.</p></section><section class=\"entry-section\"><h3>Precauciones</h3><p>Mayo lenta absorción de medicamentos, separados de las píldoras por un par de horas por consejo farmacéutico. Embarazo: pregunte al médico. La textura puede desencadenar el gagging: vaya lentamente. No es un sustituto para evaluar hemorragias, úlceras o trastornos deglución.</p></section>" };
window.RECIPE_LOCALES["pt"] = {};
window.RECIPE_LOCALES["pt"]["primer-a"] = { title: "Guia prático: preparação de comunicações e bases de segurança", html: "<section class=\"entry-section\"><h3>Bases compostas de segurança (leia antes de qualquer receita)</h3><p>1.<strong>Ferramentas limpas.</strong>Lave as mãos, frascos, tampas, colheres e coador. Para extratos de álcool ou vinagre, comece com ervas secas e frascos secos para reduzir o risco de deterioração. 2.<strong>Marca tudo.</strong>Nome, ingredientes, data fabricada, álcool % se aplicável, e “apenas externo” se for verdade. Os jarros não marcados são como os acidentes acontecem. 3.<strong>Conheça sua planta.</strong>Use ervas secas de qualidade culinária ou corretamente identificadas de fornecedores respeitáveis. Nunca forrage a menos que você é treinado; sósia pode ser tóxico. 4.<strong>Iniciar baixo.</strong>Primeiro uso: pequena quantidade, cuidado com a alergia (comichão, inchaço, urticária, problemas respiratórios → cuidados de emergência). 5.<strong>Gravidez, amamentação, crianças.</strong>Muitas ervas são<strong>não</strong>apropriado. Quando uma receita não diz explicitamente “ Série de temperos de cozinha”, assuma<strong>perguntar a um clínico primeiro</strong>. O mel é<strong>nunca</strong>para lactentes com menos de 1 ano (risco de botulismo). 6.<strong>Medicamentos.</strong>Herbs podem interagir com drogas.<strong>Nunca interrompa um medicamento prescritos</strong>baseado neste documento – pergunte a um farmacêutico ou clínico. 7.<strong>Óleos essenciais (OE).</strong>Não é o mesmo que ervas secas no chá.<strong>Não tome</strong>ocasionalmente EO. Para uso tópico, diluir fortemente em um óleo portador e patch-teste. Mantenha longe dos olhos, ouvidos internosbulinos, membranas82, gaiolas de animais de estimação e crianças sem supervisão. 8.<strong>Quando devo deitar fora.</strong>Molde, jogadores, aromas, fricção que não deveria estar lá, óleo nublado que estava claro, ou depois de uma janela de prateleira sensível → descartar. Quando não tiver a certeza, deite-a fora. 9.<strong>Quando ver um clínico.</strong>febre alta, dificuldade em respirar, dor no peito, desidratação grave, fezes / vômito, perda de peso inexplicável, feridas que pioram, suspeita de envenenamento, crise psiquiátrica, ou qualquer sintoma que o assusta. Artesanato de cozinha de ervas é<strong>não</strong>cuidados urgentes.</p></section><section class=\"entry-section\"><h3>Perfusão (chá – partes delicadas)</h3><p><strong>O que é:</strong>Água quente derramada sobre folhas, flores, ou partes de plantas macias; coberta.</p><p><strong>Método básico:</strong>Use cerca de<strong>1-2 colheres de chá de ervas secas</strong>(ou um pequeno punhado de fresco) por<strong>8 oz (240 ml)</strong>água quase fervente. Cubra 5-15 minutos. Deformação.</p><p><strong>Segurança:</strong>Cobertura mantém óleos aromáticos no copo. Não assuma “natural = ilimitado”. Deitar fora as sobras de chá depois de um dia no frigorífico, ou mais cedo se cheirar mal.</p></section><section class=\"entry-section\"><h3>Decocção (ferverizador — peças mais duras)</h3><p><strong>O que é:</strong>Raízes, cascas, subzonas, sementes ou material lenhoso fervido em água.</p><p><strong>Método básico:</strong>Sobre<strong>1 colher de chá para 1 colher de sopa de material duro</strong>por copo de água; leve a ferver, em seguida, leve ferver<strong>10-20 minutos</strong>coberto; estirpe.</p><p>2001 Segurança:**Maior calor extrai mais constituintes, incluindo amargos ou irritantes. Não decoct flores delicadas da mesma forma (eles muitas vezes se tornam planas ou ásperas).</p></section><section class=\"entry-section\"><h3>Tintura (extrato de álcool)</h3><p><strong>O que é:</strong>Material vegetal macerado em etanol (ou etanol-água) durante semanas, então prensado/treinado.</p><p>XX ColumnX padrão de cozinha educacional (adultos):<strong>Muitas vezes, aproximadamente</strong>1 parte de erva seca em peso para 5 partes líquidas em volume<strong>(um povo comum “1:5”), usando</strong>40–60% álcool<strong>(80–120 bebidas vodca classe prova) para muitas ervas folhosas / aromáticos. Raízes podem precisar de maior prova na prática profissional—</strong>este primer não o treina como farmacêutico.**</p><p><strong>Passos esboço:</strong>Chop/crush erva → jar → cobrir completamente com álcool → etiqueta → agitar diariamente → esperar<strong>2–6 semanas</strong>→ estirpe → frasco em frascos conta-gotas → etiqueta com álcool % e data.</p><p><strong>Segurança:</strong>Manter longe das crianças. Não para pessoas que têm de evitar o álcool. Gravidez: geralmente evitar tinturas medicinais, a menos que um clínico dirige. A vida útil da prateleira de uma tintura bem feita à prova de alta é frequentemente<strong>X anos</strong>se armazenado fresco/escuro; descartar se turvo com crescimento ou odor estranho.<strong>Glicerites</strong>(extratos de glicerina) são um método diferente com vida útil mais curta — estudo antes de substituir.</p></section><section class=\"entry-section\"><h3>Syrup (mel ou açúcar + chá forte / decocção)</h3><p><strong>O que é:</strong>Líquido adoçado, estabilizado na prateleira para um agradável gole (tradição alimentar).</p><p><strong>Segurança:</strong>Gelar xaropes caseiros. A vida típica do frigorífico doméstico é frequentemente discutida como<strong>semanas a alguns meses</strong>dependendo da relação açúcar/mel e limpeza –<strong>quando em dúvida, descartar</strong>.<strong>Sem mel para crianças menores de 1.</strong>Diabéticos: xaropes são açúcar – pergunte a um clínico. Os xaropes são<strong>veículos alimentares</strong>, não curas de doenças.</p></section><section class=\"entry-section\"><h3>Salve / pomada (óleo + cera de abelha)</h3><p><strong>O que é:</strong>Óleo infundido com ervas espessado com cera de abelha para aplicação na pele externa.</p><p><strong>Taxa básica de alfabetização:</strong>Muitos crafters home start near<strong>1 oz (28 g) beeswax per 1 xícara (240 ml) infundida óleo</strong>, em seguida, ajustar mais firme / mais suave. Derreta suavemente, despeje em latas, fresco, etiqueta<strong>USO EXTERNO</strong>.</p><p><strong>Segurança:</strong>Patch-test. Não coloque pomadas nos olhos, feridas profundas de punção ou feridas infectadas que necessitem de cuidados médicos. Alergia à cera de abelha é possível. Mantenha as tampas limpas.</p></section><section class=\"entry-section\"><h3>Poultice (erva fresca ou umedecido na pele)</h3><p><strong>O que é:</strong>Planta úmida esmagada aplicada externamente, muitas vezes com um pano limpo.</p><p><strong>Segurança:</strong>Contato curto; atenção à irritação. Não pulverize sobre a pele quebrada com plantas selvagens desconhecidas. Retire se começar a arder ou a formação de bolhas.</p></section><section class=\"entry-section\"><h3>Vinagre (extratos acéticos / oximels)</h3><p><strong>O que é:</strong>Ervas mergulhadas em vinagre de maçã ou vinho; às vezes o mel é adicionado mais tarde (tradição oximel).</p><p><strong>Segurança:</strong>Use vinagre de qualidade alimentar (ácido acético ~5%). Evitar tampas metálicas em contacto com vinagre a longo prazo (utilizar plástico forrado ou vidro). Frigorífico se você adicionar alho / cebola fresca ou diluir com água / mel. Os vinagres culinários não são curas para pragas ou substitutos desinfetantes para infecções clínicas.</p></section>" };
window.RECIPE_LOCALES["pt"]["primer-b"] = { title: "Orientação em quatro passos para combinar ervas com cuidado", html: "<p>Esta é a alfabetização de sinergia****, não uma licença para inventar “pilha de milagres”.</p><section class=\"entry-section\"><h3>Passo 1 — Nomeie um propósito tradicional claro</h3><p>Exemplo: “tea pós-alimentação,” não “descox seu fígado e matar patógenos.” Mega-objetivos vagos convidam empilhamento inseguro.</p></section><section class=\"entry-section\"><h3>Passo 2 — Escolha uma simples erva “lead” que você já tolera</h3><p>Uma erva culinária familiar ou suave primeiro (peppermint, gengibre, camomila, bálsamo de limão). Confirme não haver alergia nem conflito com os seus medicamentos.</p></section><section class=\"entry-section\"><h3>Passo 3 — Adicionar no máximo um ou dois parceiros de apoio com um papel tradicional relacionado</h3><p>-<strong>Acompanhantes aromáticos</strong>(fennel com hortelã) para folclore digestivo. -<strong>Companheiros de mucilagem calmantes</strong>(folha marshmallow <em>instead of</em> olmo escorregadio colhida quando possível). -<strong>Balanceadores de sabor</strong>(uma pitada de canela no leite de ouro)—O sabor é a administração, não uma alegação de drogas. Evite misturar muitos ativos fortes (laxantes + sedativos + estimulante amargos + EOs) “porque mais é melhor.”</p></section><section class=\"entry-section\"><h3>Passo 4 — Reveja alerta como um conjunto, em seguida, reavaliar</h3><p>Pergunte: gravidez? Crianças? Diluentes de sangue? Cirurgia em breve? sensibilidade ao álcool? integridade da pele? Se alguma resposta for incerta,<strong>simplificar para alimentos</strong>ou<strong>pedir a um clínico</strong>. Mantenha um diário de uso curto (o que, quanto, como se sentiu). Pára se te sentires pior. Combinando ervas<strong>não</strong>multiplicar santidade ou garantia de benefício - a humildade é parte da sabedoria (cf. o espírito de Provérbios &#x27; louvor do conhecimento com prudência).</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-garden-settling-digestive-tea"] = { title: "1. Jardim Setting Digestive Tea", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Um chá aromático pós-refeição suave na longa tradição de cozinha dos digestivos de hortelã e semente — folclore de conforto, não um diagnóstico de “IBS” ou úlcera doença.</p></section><section class=\"entry-section\"><h3>Ingredientes (1 caneca)</h3><ul><li>1 tsp folha seca de hortelã-pimenta (<em>Mentha × piperita</em>)</li><li>1 tsp semente de funcho triturada (<em>Foeniculum vulgare</em>)</li><li>8 oz (240 ml) água perto de ebulição</li><li>Opcional: fina fatia de gengibre fresco ou algumas folhas de bálsamo de limão</li></ul></section><section class=\"entry-section\"><h3>Passos</h3><p>X</p><ol><li>1. Combine ervas em um copo ou chaleira.</li><li>2. Despeje água quente; cubra 10 minutos.</li><li>3. Strain; gole quente após uma refeição.</li><li>4. Não adoce muito se estiver a observar açúcar no sangue — mel opcional apenas para adultos/crianças mais velhas por orientação clínica.</li></ol></section><section class=\"entry-section\"><h3>Armazenamento</h3><p>Beba fresco. Refrigerar as sobras até 24 horas; descartar se desligado.</p></section><section class=\"entry-section\"><h3>Precauções</h3><p>A hortelã-pimenta pode piorar o refluxo em algumas pessoas. Fennel é geralmente culinária, mas quantidades medicinais na gravidez garantem aconselhamento clínico; alergias raros Apiaceae existem. Óleo essencial de hortelã-pimenta/fennel é<strong>não</strong>um substituto para este chá e é<strong>não</strong>para uso interno casual.</p></section><section class=\"entry-section\"><h3>Nota de criação</h3><p>As ervas de jardim aromáticos se encaixam no padrão bíblico maior de plantas dadas para alimento e vida cuidadosa (Gênesis 1:29)—sem inventar um “verso de milagre digestivo”.</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-quiet-evening-lemon-balm-chamomile-cup"] = { title: "2. Quiet Evening Lemon Balm & Camomile Cup", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Um copo suave associado ao herbalismo popular com calma e calma – não um tratamento para transtornos de ansiedade, insônia ou depressão.</p></section><section class=\"entry-section\"><h3>Ingredientes (1 caneca)</h3><p>guinea</p><ul><li>1 tsp erva-cidreira seca (<em>Melissa officinalis</em>)</li><li>1 tsp flores secas de camomila alemã (<em>Matricaria chamomilla</em>)</li><li>8 oz (240 ml) de água quase a ferver</li></ul></section><section class=\"entry-section\"><h3>X Passos</h3><p>X</p><ol><li>1. Coloque ervas em uma caneca ou pote coberto.</li><li>2. Steep 5-10 minutos (camomila pode ficar amarga se sobre-esticado para alguns palatos).</li><li>3. Strain; gole à noite longe de telas se você gosta de um ritual de vento.</li><li>4. Gorzzle de mel adulto opcional.</li></ol></section><section class=\"entry-section\"><h3>Armazenamento</h3><p>Uso fresco preferido.</p></section><section class=\"entry-section\"><h3>Precauções</h3><p>A camomila está na família das margaridas — evite se você tem fortes alergias ao ragweed/crisântemo. Bálsamo limão pode teoricamente afetar laboratórios de tireóide/medicamentos em uso concentrado – pergunte se você tem doença tireoidiana. Sedar pilhas com medicamentos prescritos para o sono precisa de conselhos clínicos. Não é um substituto para cuidados de saúde mental.</p></section><section class=\"entry-section\"><h3>Nota de Escrita/criação</h3><p>Nenhuma forçada; gratidão pelo descanso noturno é suficiente.</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-mullein-leaf-respiratory-steam-cup-tea"] = { title: "3. Xícara de vapor respiratório de folha de verbasco (chá)", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Uso tradicional da folha de mullein como um calmante chá de estação respiratória/aroma de vapor –<strong>não</strong>uma pneumonia, COVID, asma ou tratamento de tuberculose.</p></section><section class=\"entry-section\"><h3>Ingredientes (1 caneca)</h3><ul><li>1–2 tsp folha seca de verbasco (<em>Verbascum thapsus</em>), de preferência cortada e peneirada</li><li>8–10 oz água</li><li>filtro fino de coador ou café (pelos mullein pode irritar gargantas)</li></ul></section><section class=\"entry-section\"><h3>Passos</h3><p>X</p><ol><li>1. Despeje água quente sobre a folha; cubra 10-15 minutos.</li><li>2. Strain<strong>muito bem</strong>através de um filtro fino para remover cabelos irritantes.</li><li>3. Sip quente, ou inalar vapor cautelosamente a partir de uma distância segura (sem queimaduras).</li><li>4. Limite para uso de pessoas sazonais curto, a menos que um clínico aconselha de outra forma.</li></ol></section><section class=\"entry-section\"><h3>Armazenamento</h3><p>Fresh.</p></section><section class=\"entry-section\"><h3>Precauções</h3><p>Não use mullein <em>seeds</em> ou folha fuzzy não filtrada casualmente. A asma e problemas respiratórios graves precisam de cuidados médicos – o chá não é um inalador. Gravidez: pergunte primeiro. Fumaça folclore existe historicamente;<strong>esta receita não incentiva ervas fumantes.</strong></p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-fresh-ginger-root-comfort-tea"] = { title: "4. Chá reconfortante de gengibre fresco", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Classic chá de cozinha para dias frios e estômago instável folclore — educação de nível alimentar, não prescrição terapia antiemética.</p></section><section class=\"entry-section\"><h3>Ingredientes (1 caneca)</h3><ul><li>3–5 fatias finas de gengibre fresco (~1–2 tsp ralado)</li><li>8–10 oz água</li><li>Opcional: fatia de limão; mel adulto para provar</li></ul></section><section class=\"entry-section\"><h3>Passos</h3><ol><li>1. Ferva suavemente 10 minutos (estilo de decocção) ou gengibre ralado em água quase fervente 10 minutos.</li><li>2. Strain; adicione limão/mel se desejar.</li><li>3. Sip quente.</li></ol></section><section class=\"entry-section\"><h3>Armazenamento</h3><p>Fresco; resto de chá refrigerado ~24 horas.</p></section><section class=\"entry-section\"><h3>Precauções</h3><p>Ginger pode interagir com anticoagulantes e pode incomodar cálculos biliares ou refluxo em algumas pessoas – pergunte a um clínico se for relevante. As megadoses medicinais na gravidez pertencem à orientação clínica, não aos desafios da internet. Óleo essencial de gengibre é<strong>não</strong>para uso interno casual.</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-rosemary-folklore-clarity-tea-honest-limits"] = { title: "5. Rosemary Folklore Clarity Tea (limites honestos)", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Chá de alecrim culinário ligado no folclore mediterrâneo com “remembrança” e simbolismo de alerta –</p></section><section class=\"entry-section\"><h3>limite honesto</h3><p>este não é um medicamento comprovado Alzheimer ou reforço de QI.</p><p>XXBX ceramic1 Ingredientes (1 caneca):**</p><ul><li>1 tsp folha seca de alecrim (<em>Salvia rosmarinus</em> / <em>Rosmarinus officinalis</em>), esfarelada</li><li>8 oz Água quase fervente</li></ul></section><section class=\"entry-section\"><h3>Passos</h3><p>X</p><ol><li>1. Estepe coberto 5-8 minutos (mais longo fica bastante amargo/camporoso).</li><li>2. Strain; saborear ocasionalmente como um chá de ervas culinárias.</li><li>3. Pare com uma caminhada e um bom sono — folclore sem pensar mágico.</li></ol></section><section class=\"entry-section\"><h3>Armazenamento</h3><p>Fresh.</p></section><section class=\"entry-section\"><h3>Precauções</h3><p>Evite grandes quantidades de medicamentos na gravidez. Epilepsia ou forte sensibilidade à cânfora: pergunte a um clínico. Óleo essencial de Rosemary<strong>**é concentrado – só aromático/topical diluído,</strong>não**oral DIY. As pessoas com pressão arterial elevada em medicamentos devem limpar experiências de ervas com um clínico.</p></section><section class=\"entry-section\"><h3>Nota de criação</h3><p>Rosemary é um presente de cozinhas mediterrâneas; folclore memória é poesia cultural, não uma reivindicação clínica.</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-spring-nettle-leaf-food-like-tea"] = { title: "6. Chá alimentar primaveril de folha de urtiga", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Nurishing food-like infusion de folha de urtiga picada seca — tradição de comida popular rica em minerais, não uma cura “limpador de sangue”.</p></section><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>1–2 tsp folha de urtiga seca (<em>Urtica dioica</em>) por 8 oz água</li></ul><p>(ou 1 Tbsp por caneca para uma cerveja tipo alimento mais forte algumas tradições preferem)</p></section><section class=\"entry-section\"><h3>Passos</h3><p>X</p><ol><li>1. Despeje água quase fervente sobre folha seca; cubra de 10 a 15 minutos (algumas íngremes a mais para um estilo de “nutrição” – o sabor será mais profundo/terrestre).</li><li>2. Strain; beba como um chá verde salgado.</li><li>3. Opcional: pitada de hortelã para suavizar o sabor gramado.</li></ol></section><section class=\"entry-section\"><h3>Armazenamento</h3><p>Fresco ou refrigerado até 24 horas.</p></section><section class=\"entry-section\"><h3>Precauções</h3><p>Use<strong>seco</strong>ou folha completamente cozida — picada fresca de urtigas cruas. Pode ser diurético; pergunte se está a tomar medicamentos para a tensão arterial, diabetes ou diminutos no sangue ou se tem doença renal. Alergia rara possível. Forragem apenas com ID especialista (somos de aparência existem em algumas regiões).</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-kitchen-turmeric-golden-milk"] = { title: "7. Cozinha Leite Dourado Açafrão", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Uma bebida láctea quente e temperada da tradição da cozinha sul-asiática – alimento de conforto com açafrão, não um “fármaco anti-inflamatório” ou protocolo de câncer.</p></section><section class=\"entry-section\"><h3>Ingredientes (1 caneca)</h3><ul><li>1 xícara (240 ml) de leite à escolha (lácteo ou vegetal sem açúcar)</li><li>½–1 tsp açafrão-da-terra em pó (<em>Curcuma longa</em>)</li><li>Pitada pequena pimenta preta (tradi folclore de emparelhamento tradicional para a cúrcuma culinária)</li><li>Opcional: 1⁄4 tsp canela; fatia de gengibre fresco; mel adulto para provar</li></ul></section><section class=\"entry-section\"><h3>Passos contrapartes</h3><ol><li>1. Açafrão (e especiarias opcionais) em um respingo de leite frio para fazer uma pasta suave.</li><li>2. Aqueça suavemente o leite restante — não queime.</li><li>3. Whisk na pasta; ferver muito suavemente 3-5 minutos.</li><li>4. Adoçar levemente, se desejar; tomar um gole quente.</li></ol></section><section class=\"entry-section\"><h3>Armazenamento</h3><p>Melhor fresco; sobras refrigerados ~24 horas; reaquecer uma vez.</p></section><section class=\"entry-section\"><h3>Precauções</h3><p>Os suplementos de açafrão/curcumina são<strong>não</strong>o mesmo que o pó de cozinha – extratos de alta dose podem interagir com anticoagulantes e afetar a doença da vesícula biliar. Gravidez: manter a quantidade de alimentos, a menos que o clínico dirija. Roupas e balcões.<strong>Nunca</strong>apresentar leite de ouro como uma receita anti-câncer.</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-dark-berries-immune-season-elderberry-syrup-food-tradition"] = { title: "8. Bagas escuras Xarope de amora-esposa (tradição alimentar)", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Xarope de amora-espinho cozido na tradição alimentar de época fria das cozinhas europeias —<strong>não</strong>cura da gripe, tratamento COVID ou substituição vacinal.</p></section><section class=\"entry-section\"><h3>Ingredientes (cerca de 2-3 xícaras de xarope, varia)</h3><ul><li>1 xícara de bagas pretas secas (<em>Sambucus nigra</em> bagas maduras apenas)<strong>ou</strong>~2 xícaras congeladas maduros bagas pretas</li><li>3 xícaras de água</li><li>1 pau de canela (opcional)</li><li>3-5 fatias de gengibre fresco (opcional)</li><li>1 xícara de mel (ou para provar; adicione<strong>X fora de calor</strong>)</li></ul></section><section class=\"entry-section\"><h3>Passos</h3><p>X</p><ol><li>1. Mergulhar bagas (e especiarias opcionais) em água cerca de 30-45 minutos até que o líquido reduz em aproximadamente um terço para metade.</li><li>2. Mash levemente; coar através de uma malha fina ou pano (evitar esguichar nos olhos).</li><li>3. Fresco até quente, não quente; mexa em mel.</li><li>4. Frasco em vidro limpo; rótulo e data; refrigerador.</li></ol></section><section class=\"entry-section\"><h3>Armazenamento</h3><p>Refrigerado; ensino doméstico típico muitas vezes tem como objetivo usar dentro de<strong>1–3 meses</strong>—descarte em molde, fermento de frizz, ou odor fora.</p></section><section class=\"entry-section\"><h3>Precauções</h3><p>Use apenas<strong>maduro cozido</strong>amoras pretas de fontes de confiança <em>S. nigra</em>. Bagas cruas, folhas, cascas e outras partes <em>Sambucus</em> podem causar náuseas. Doença auto-imune ou medicamentos imunossupressores: pergunte a um clínico antes de “imune” uso folclórico.<strong>Sem mel para lactentes com menos de 1.</strong>Diabetes: matéria de carga de açúcar. Esta é a educação da tradição alimentar – não uma alegação antiviral.</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-garlic-in-honey-folk-preserve-food"] = { title: "9. Alho em mel Folk Preserve (food)", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Dente de alho descascado preservado em mel como condimento de comida popular – interesse culinário, não uma substituição de antibiótico.</p></section><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>Dente de alho descascado para encher frouxamente um pequeno frasco limpo (cerca de 1 dente de xícara)</li><li>Mel bastante cru ou pasteurizado para cobrir completamente</li></ul></section><section class=\"entry-section\"><h3>Passos</h3><ol><li>1. Use dentes secos, unblemished; esmagamento de luz opcional.</li><li>2. Coloque em frasco; cubra totalmente com mel; solte bolhas de ar com um pauzinho limpo.</li><li>3. Tampa vagamente no início, se o alho muito fresco libera gases; em seguida, selar.</li><li>4. Conservar fresco/escuro; os cravos amolecem durante dias a semanas. Use como um chuvisco / condimento de alimentos.</li></ol></section><section class=\"entry-section\"><h3>Armazenamento</h3><p>Fresco despensa ou geladeira; cuidado para espuma ou molde incomum – descarte se suspeito. Alguns preferem refrigeração por precaução.</p></section><section class=\"entry-section\"><h3>Precauções</h3><p>As conversas de risco de botulismo existem em torno de baixo ácido alho-em-óleo; mel-ágaro é uma matriz diferente, mas ainda requer limpeza e bom senso -<strong>não dar aos lactentes.</strong>Alho pode aumentar a tendência de sangramento e interagir com medicamentos para HIV e anticoagulantes – pergunte se relevante. Uso de alimentos □ tratamento de infecção no lugar de cuidados médicos.</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-honey-onion-household-cough-syrup-food-tradition"] = { title: "10. Xarope de tosse doméstica com cebola (tradição alimentar)", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Casa antiga doce xarope de cebola e mel para acalmar o folclore dolorido – tradição alimentar, não cuidado com pneumonia.</p></section><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>1 cebola média, finamente cortada</li><li>Mel suficiente para cobrir fatias em um frasco (cerca de 1⁄2-1 xícara)</li></ul></section><section class=\"entry-section\"><h3>Passos</h3><ol><li>1. Camada de cebola em um frasco limpo; cubra com mel.</li><li>2. Deixe sentar 2-4 horas (ou durante a noite no frigorífico) até formar líquido xarope.</li><li>3. Esforço líquido em um frasco limpo; descartar sólidos ou usar na cozinha, se desejar.</li><li>4. Adultos: colherinhos pequenos como um xarope de alimentos calmante. Crianças mais velhas: apenas com julgamento clínico/pai;<strong>nunca menor de 1 anos (querida).</strong></li></ol></section><section class=\"entry-section\"><h3>Armazenamento</h3><p>Refrigeração; usar dentro de ~ 1 semana; descartar se desligado.</p></section><section class=\"entry-section\"><h3>Precauções</h3><p>tosse persistente, febre alta, ou dificuldade respiratória → clínico. Querida, não para bebés. Cebola pode incomodar refluxovital.</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-sunshine-calendula-infused-oil"] = { title: "11. Sunshine Calendula Infunded Oil", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Óleo infundido com pétalas de calêndula para folclore externo de conforto da pele — manchas secas e artesanato de pele rachada, não tratamento de infecção.</p></section><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>1 xícara de pétalas de calêndula secas (<em>Calendula officinalis</em>)</li><li>11⁄4-11⁄2 xícaras de azeite (suficiente para cobrir por ~1 polegada)</li></ul></section><section class=\"entry-section\"><h3>Passos (método quente)</h3><p>X</p><ol><li>1. Coloque pétalas em um frasco seco limpo; cubra completamente com óleo.</li><li>2. Coloque o frasco em um banho de água quente ou calor tipo iogurte<strong>bem abaixo do calor de fritar</strong>por várias horas, ou método folk de janela ensolarada por 1-2 semanas (evitar superaquecimento/esfumamento).</li><li>3. Agitar suavemente quandovitar lembrar.</li><li>4. Estirpe através de pano; frasco; etiqueta<strong>USO EXTERNO</strong>com data.</li></ol></section><section class=\"entry-section\"><h3>Armazenamento</h3><p>Fresco/escuro; muitas vezes meses se erva seca e processo limpo—descartar se turvo, mofado, ou ranço-smelling.</p></section><section class=\"entry-section\"><h3>Precauções</h3><p>Alergia à família Daisy possível. Apenas externo. Não administrar aos olhos.vitar a injecção. Feridas profundas ou infecvitadas precisam de cuidados médicos.</p></section><section class=\"entry-section\"><h3>Nota de criação</h3><p>As pétalas de marigold-brilhante são uma humilde misericórdia de jardim para as mãos que trabalham o solo.</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-calendula-garden-salve"] = { title: "12. Pomada de calêndula do jardim", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Óleo de calêndula enrugado de cera de abelha para embarcações de pele rachada externa.</p></section><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>1 xícara de calêndula infundida (Recipe 11)</li><li>~1 oz (28 g) cera de abelha (pastilhas ou ralado) - ajuste para o conjunto mais firme/mais suave</li><li>Opcional: 1–2 tsp óleo de vitamina E como folclore antioxidante para a vida útil (não uma alegação de medicamento)</li></ul></section><section class=\"entry-section\"><h3>Passos</h3><ol><li>1. Derreter suavemente óleo + cera de abelha em uma caldeira dupla até que apenas combinado.</li><li>2. Retire do calor; vitamina E opcional.</li><li>3. Despeje em latas limpas; arrefeça sem perturbação.</li><li>4. Rótulo<strong>SOMENTE USO EXTERNO</strong>, data, ingredientes.</li></ol></section><section class=\"entry-section\"><h3>Armazenamento</h3><p>Fresco/escuro; muitas vezes muitos meses; descarte se o cheiro ficar rançoso.</p></section><section class=\"entry-section\"><h3>Precauções</h3><p>Teste de patch. É possível alergia à cera de abelha. Não para feridas profundas, mordidas de animais, ou uso de olhos.</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-aloe-leaf-gel-external-cool-note"] = { title: "13. Gel de Folha de Aloe — Nota externa fresca", html: "<section class=\"entry-section\"><h3>Propósito (educativo/ ammunition)</h3><p>Gel fresco de folhas internas usado externamente em muitas culturas para acalmar a pele queimada ou irritada ao sol — nota externa educacional, não cuidados de queimados.</p></section><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>1 folha exterior madura de <em>Aloe vera</em> (planta de qualidade alimento-cosmética, pesticida-consciente)</li></ul></section><section class=\"entry-section\"><h3>Passos</h3><ol><li>1. Enxaguar a folha; aparar picos.</li><li>2. Fillet para expor gel interiornard claro; evitar látex amarelo logo sob a pele, quando possível (látex é um estimulante laxante e pode irritar).</li><li>3. Scoop gel claro; mistura curta opcional para suavidade.</li><li>4. Aplicar uma camada fina<strong>externamente</strong>na pele intacta aquecida ao sol; refrigerar os restos de gel em um frasco limpo e usar dentro de alguns dias.</li></ol></section><section class=\"entry-section\"><h3>Armazenamento</h3><p>Geladeira; poucos dias; descarte se o despojo viscoscos rosa/marrom aparecer.</p></section><section class=\"entry-section\"><h3>Precauções</h3><p>Teste de patch. Não utilizar em queimaduras graves (procure cuidados médicos). látex oralmente é**não</p></section><section class=\"entry-section\"><h3>recomendado aqui - riscos estimulantes laxantes, contraindicação da gravidez no ensino tradicional, e problemas de segurança regulatória. Os óleos essenciais não pertencem a este gel para experiências casuais “mais fortes”.\n\nXX cortinas</h3><p>Os “alos” bíblicos em alguns versos provavelmente se referem a aromáticos perfumados de madeira de águia,<strong>não</strong>idêntico ao gel <em>Aloe vera</em> moderno — ensinar a distinção honestamente (ver monografia de Aloes).</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-plantain-leaf-field-poultice"] = { title: "14. Campo de Folha de Plantain", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Póltico externo popular clássico de plantina de folhas largas ou de nervuras para pequenos arranhões e folclore de picadas de insetos — educação de primeiros socorros adjacentes, não cuidados de emergência.</p></section><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>Várias folhas limpas <em>Plantago major</em> ou <em>P. lanceolata</em> (identificação positiva necessária)</li><li>Água limpa; pano limpo</li></ul><p>XX lubrificantes:**</p><ol><li>1. Lavar as folhas bem.</li><li>2. Mastigue brevemente<strong>somente se você confiar em</strong>e sua boca estiver saudável – ou esmague com uma colher limpa para contusões e umedecimento.</li><li>3. Aplicar em áreas superficiais intactas ou muito pequenas da pele; cobrir levemente com pano 10-20 minutos.</li><li>4. Remova; lave a pele pousou; vigie para irritação.</li></ol></section><section class=\"entry-section\"><h3>Armazenamento</h3><p>Utilizar folhas frescas; não armazenar um cataplasma mastigado.</p></section><section class=\"entry-section\"><h3>Precauções</h3><p>O ID errado da planta é perigoso – não improvise se não tiver certeza. Punções profundas, sinais de infecção, picadas de carrapato de preocupação, ou mordidas de animais → clínico. Não utilize cataplasmas mastigados na boca em pessoas imunocomprometidas sem aconselhamento clínico.</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-comfrey-leaf-external-only-salve-note"] = { title: "15. Nota de pomada somente externa de folha de confrei", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Entrada de ensino para<strong>somente para o exterior</strong>comfrey craft literacy – e uma linha dura contra o uso interno.</p></section><section class=\"entry-section\"><h3>Ingredientes (padrão externo educacional)</h3><ul><li>1 cup folha seca de confrei (<em>Symphytum officinale</em>) infundida em azeite (mesmo método do óleo de calêndula)</li><li>Cera de abelha para salvar consistência (~1 oz por óleo de xícara como ponto de partida)</li></ul><p>XXBXΖ Passos: XXssessores</p><ol><li>1. Infundir óleo**folha</li></ol></section><section class=\"entry-section\"><h3>com ervas secas e processo limpo; estirpe.\n2. Faça pomada como na Receita 12.\n3. Rótulo em negrito</h3><p>SOMENTE USO EXTERNO — NÃO INGEST**.</p><ol><li>4. Use com moderação na pele não quebrada para a educação tradicional de hematomas/esprain folclore.</li></ol></section><section class=\"entry-section\"><h3>Armazenamento</h3><p>Fresco/escuro; rejeitar se rançoso.</p></section><section class=\"entry-section\"><h3>Precauções (críticas)</h3><p>Comfrey contém<strong>alcaloides pirrolizidínicos (PAs)</strong>associados a toxicidade hepática grave quando tomados internamente.<strong>Sem chá, sem smoothies, sem tinturas internas neste currículo.</strong>Evite feridas profundas ou pele partida onde a absorção aumenta. Evite na gravidez, enfermagem e em crianças. Prefere produtos profissionais reduzidos por PA se um clínico alguma vez recomendar um tópico de tipo comfrey – e ainda tratar como ensino apenas externo.</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-lavender-linen-sachet-dilute-topical-note"] = { title: "16. Saquete de linho de lavanda & Dilute Nota Topical", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Lavanda seca para fragrância de linho e <em>highly diluted</em> aroma tópico — não medicina oral essencial-óleo.</p></section><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>1⁄2–1 colheres de alfazema secas (<em>Lavandula angustifolia</em>) para saquetas</li><li>Para diluir Concursos postais (adultos): 1 gota de óleo essencial de lavanda em 1 tsp (5 ml)</li></ul></section><section class=\"entry-section\"><h3>Passos (saco)</h3><ol><li>1. Encher pequenos sacos de pano com botões secos; gravata fechada.</li><li>2. O que é o que se refere ao facto de ter sido necessário para o efeito.</li><li>3. Refresque quando o cheiro desaparecer.</li></ol></section><section class=\"entry-section\"><h3>Passos (diluir opcional tópico)</h3><ol><li>1. Misture EO cadáveres no suporte; teste de sistema transdérmico no braço interno 24 horas.</li><li>2. Mancha na pele do ponto de pulso, se tolerada.</li><li>3. Lave as mãos depois; mantenha- se afastado dos olhos.</li></ol></section><section class=\"entry-section\"><h3>Armazenamento</h3><p>Buds secos herméticos/frio; garrafas EO escuro/frio, à prova de crianças.</p></section><section class=\"entry-section\"><h3>Precauções</h3><p>XXBX Não ingerir óleo essencial de lavanda casualmente.**Algumas pessoas têm dores de cabeça de forte cheiro. Animais de estimação2/animais (especialmente gatos) podem ser sensíveis a EOsonventilate; não se aplicam a animais sem orientação veterinária. Crianças: apegue-se às saquetas secas, a menos que um clínico aconselhe.</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-rosemary-garden-hair-rinse"] = { title: "17. Rosemary Jardim Cabelo Enxaguar", html: "<p>XXBX2011 Propósito (educativo/tradicional):**X Chá diluído de alecrim como um enxaguamento de cabelo final na tradição cosmética popular — folclore de frescor, não uma cura de alopecia médica.</p><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>bancos 2 Tbsp alecrim seco</li><li>2 xícaras de água</li><li>Opcional: 1 Tbsp vinagre de maçã-cider no enxaguamento refrigerado (tradição folclórica de escamas)</li></ul></section><section class=\"entry-section\"><h3>Passos</h3><ol><li>1. Alecrim em água 10-15 minutos; fresco; coar bem.</li><li>2. Após shampoo/condição normal, enxaguar sobre o cabelo/escalpa.</li><li>3. Não enxaguar a menos que prefira; estilo como de costume.</li><li>4. Utilizar ocasionalmente; descontinuar se a irritação.</li></ol></section><section class=\"entry-section\"><h3>Armazenamento</h3><p>Frigorífico chá enxaguar até 3 dias; descartar se turva / off.</p></section><section class=\"entry-section\"><h3>Precauções</h3><p>Manter fora dos olhos. As condições do escalpe (psoríase, infecção) necessitam de cuidados clínicos. EO enxaguamentos são um ofício diferente, de alto risco - esta receita usa chá, não óleo essencial reto.</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-four-aromatics-historical-vinegar-culinary-cleaning-adjacent"] = { title: "18. Quatro Aromatics Historical Vinagre (culinário / limpeza- adjacente)", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Um vinagre aromático original no <em>spirit</em> do folclore “quatro ladrões” moderno -<strong>alfabetização história + culinária / limpeza-adjacente uso doméstico</strong>. É<strong>não</strong>uma cura praga, antiviral, ou substituto para vacinas, antibióticos, ou medidas de saúde pública.</p></section><section class=\"entry-section\"><h3>Honestidade histórica</h3><p>Histórias de ladrões que usam vinagre de ervas durante os anos da peste são mais tarde folclore em camadas sobre verdadeiras tradições aromáticas-vinagar. Receitas variaram amplamente; produtos modernos de marca são proprietários. Esta fórmula é uma reconstrução educacional****, não uma cópia de qualquer mistura de livro.</p></section><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>2 xícaras (480 ml) vinagre cru de maçã-cider (~5% de acidez)</li><li>1 Tbsp alecrim seco</li><li>1 Tbsp sálvia seca</li><li>1 Tbsp botões de lavanda secos</li><li>1 Tbsp tomilho seco</li><li>2–3 dentes de alho descascados (opcional; aumenta a precaução de deterioração)</li><li>1 pequeno pau de canela (opcional)</li></ul></section><section class=\"entry-section\"><h3>Passos</h3><ol><li>1. Coloque ervas (einhão/alho opcional) em um frasco de vidro limpo.</li><li>2. Cubra com vinagre por pelo menos 1 polegada; sele com tampa sem contato metálico.</li><li>3. Steep 2-4 semanas, agitando ocasionalmente; manter fresco / escuro.</li><li>4. Esforço; frasco; rótulo “ vinagre aromático culinário – não um medicamento.”</li></ol></section><section class=\"entry-section\"><h3>Armazenamento</h3><p>Despensa fresca se for apenas erva; refrigerar se for usado alho; usar em poucos meses; descartar se aparecer bolor.</p></section><section class=\"entry-section\"><h3>Usos educativos suspensos</h3><p>molhos de salada (diluídos com óleo); como um contador de cozinha limpa<strong>após</strong>limpeza adequada para o perfume (vinagar não é uma alegação desinfetante hospital). Fazer<strong>não</strong>beber como um “tônico praga detox.”</p></section><section class=\"entry-section\"><h3>Precauções</h3><p>Toalhita externa: diluir; não encharcar a pele. Culinária: o alho-vinegar não para lactentes; interações como com o alho. Gravidez: ervas de nível alimentar geralmente diferem de gulping vinagres medicinais – pergunte se não tem certeza.</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-simple-kitchen-digestive-bitters-aromatic-vinegar-style"] = { title: "19. Simples Bitters digestivos cozinha (estilo vinagre aromático)", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Um vinagre azedo aromático suave para folclore antes da refeição (apetito/pasta digestiva) – não um protocolo de “limpeza” de fígado ou parasita.</p></section><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>11⁄2 xícaras de vinagre de maçã-cidra</li><li>1 Tbsp casca seca de laranja (grau alimentar)</li><li>1 tsp raiz genciana<strong>ou</strong>omita genciana e use 1 tsp raiz de dente de leão seca para uma versão de ensino mais suave</li><li>Sementes de funcho 1 tsp</li><li>1⁄2 trge, seco, ou algumas fatias frescas</li><li>Opcional: 2–4 Tbsp mel após deformação (estilo oximel)</li></ul></section><section class=\"entry-section\"><h3>Passos</h3><ol><li>1. Combine botânicos em um frasco; cubra com vinagre.</li><li>2. Steep 2-3 semanas; agitar de vez em quando.</li><li>3. Strain; mel opcional enquanto o líquido não está quente.</li><li>4. Adultos: tradicionalmente um<strong>pequeno</strong>sabor (por exemplo, 1 colher de chá em um pouco de água) antes das refeições -<strong>parar se isso o perturba.</strong></li></ol></section><section class=\"entry-section\"><h3>Armazenamento</h3><p>Fresco/escuro; meses típicos para extratos de vinagre; descartar se estragado.</p></section><section class=\"entry-section\"><h3>Precauções</h3><p>Amargos fortes podem agravar úlceras, refluxo ou náuseas. Gentian é intensamente amargo — omite se muito severo. Gravidez: evite amargos medicinais, a menos que o clínico dirija. Não para crianças como uma “experiência tônica”. Isto não é antibioticoterapia.</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-levant-table-za-atar-style-herb-blend"] = { title: "20. Table Za’atar-Style Herb Blend", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Mistura de sésamo-erva-espinha inspirada em tradições de mesa Levantina — alegria alimentar, não uma fórmula médica. Receitas za’atar regionais variam; este é um<strong>original cozinha ensino mistura</strong>, não uma cópia de marca.</p></section><section class=\"entry-section\"><h3>Ingredientes (jardim pequeno)</h3><p>X</p><ul><li>3 Tbsp tomilho seco (ou uma mistura de tomilho + orégano)</li><li>1 Tbsp manjerona seca ou orégano adicional</li><li>2 Tbsp sementes de gergelim tostadas</li><li>1–2 tsp sumac</li><li>½–1 tsp sal fino (opcional)</li><li>Pinch opcional cominho torrado em terra</li></ul></section><section class=\"entry-section\"><h3>X Passos</h3><ol><li>1. Sementes de gergelim levemente torradas até fragrante; fresco.</li><li>2. Cromo ervas; misturar com sumac, sésamo, e opcional sal / cumina.</li><li>3. Sabor; ajuste a acidez (sumac) e o sal.</li><li>4. Sirva com azeite de oliva e pão como molho de comida.</li></ol></section><section class=\"entry-section\"><h3>Armazenamento</h3><p>Frasco hermético, fresco/escuro, ~1–3 meses para o melhor aroma.</p></section><section class=\"entry-section\"><h3>Precauções</h3><p>Alergias alimentares (sesame). Dietas sensíveis ao sal: omitir sal. Apenas culinária.</p></section><section class=\"entry-section\"><h3>Criação / cultura nota</h3><p>Partilhar pão e óleo é parente de antigos temas de hospitalidade no mundo das Escrituras — sem afirmar que este frasco de especiarias aparece em um versículo.</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-avicenna-inspired-rosewater-educational-note"] = { title: "21. Avicena-Inspirado Rosewater Educational Note", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Letramento histórico sobre água de rosas (<em>maa’ ward</em>) no patrimônio médico e culinário persa/islâmico associado a figuras como Ibn Sina (Avicena) —<strong>educação aromática/culinária</strong>, não uma reconstrução do protocolo de uma marca moderna de hidrolato com direitos autorais.</p><p><strong>:</strong>A verdadeira produção de hidrosol utiliza equipamento de destilação a vapor e know-how de rendimento/segurança. Home Os métodos de “petalas de rosa de imersão em seguida garrafa” produzem uma<strong>frágil água aromática</strong>que estraga rapidamente e é<strong>não</strong>idêntico a água de rosa destilada a vapor comercial.</p></section><section class=\"entry-section\"><h3>Água aromática caseira suave (pequena prateleira educacional)</h3><ul><li>1–2 xícaras de pétalas de rosa perfumadas sem pesticidas (<em>Rosa × damascena</em> ou rosas culinárias – não rosas de pesticida floristas)</li><li>Água apenas para cobrir</li></ul></section><section class=\"entry-section\"><h3>X Passos</h3><ol><li>1. Simmer muito suavemente, coberto, 15–20 minutos; não ferver duro para lama.</li><li>2. Fresco; estirpe; refrigerar imediatamente em vidro limpo.</li><li>3. Use dentro de<strong>vários dias</strong>como um enxágue aromático geladeira para face / pele<strong>patch-test primeiro</strong>, ou uma gota em sobremesas adultas - preferir alimentos comerciais de qualidade de água de rosa para cozinhar confiabilidade.</li><li>4. Descarte em turvação ou deterioração azeda.</li></ol></section><section class=\"entry-section\"><h3>Precauções</h3><p>O risco de spoilage é alto – quando inseguro, compre água de rosa de qualidade alimentar respeitável. Salpico externo: evite os olhos. Óleo essencial de rosa é caro e concentrado —<strong>não</strong>para uso interno casual. Gravidez: a água de rosa culinária de nível alimentar difere das alegações medicinais – mantenha-se humilde.</p></section><section class=\"entry-section\"><h3>Nota histórica</h3><p>Comemore a história intelectual da destilação sem fingir que uma panela é igual a uma sala medieval.</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-kyphi-inspired-temple-aromatics-incense-note"] = { title: "22. Kyphi-Inspirated Temple Aromatics Incense Note", html: "<section class=\"entry-section\"><h3>Propósito (educativo/tradicional)</h3><p>Nota de incenso educacional somente aromático inspirado em tradições egípcias <em>kyphi</em> e botânicas de incenso bíblico (franquinco, mirra e aromáticos hissopo-adjacentes)—<strong>X cheiro e história</strong>, não medicina pulmonar ou protocolo médico místico.</p></section><section class=\"entry-section\"><h3>Incerteza</h3><p>Antigas receitas de kyphi eram complexas (vinho, mel, resinas, muitos aromáticos) e variadas pelo texto fonte. Trata-se de uma mistura de estudo aromático<strong>simplificado moderno</strong>, não uma fórmula museu-acurada e não copiado de um livro ritual com direitos autorais.</p></section><section class=\"entry-section\"><h3>Mistura simples de estudo de resina (ventilado)</h3><ul><li>1 tsp rasgos de incenso</li><li>1⁄2 tsp rasgos de mirra</li><li>Opcional: picar hissopo seco ou casca de canela para comparação de aroma educacional</li><li>Disco de carvão projetado para incenso<strong>ou</strong>observar resinas em um aquecedor feito de propósito por instruções de dispositivo</li></ul></section><section class=\"entry-section\"><h3>Passos</h3><ol><li>1. Abrir janelas; retirar crianças/animais com sensibilidade ao fumo da sala.</li><li>2. Carvão leve com cuidado em um queimador à prova de fogo; espere até terminar – ou use uma resina elétrica mais quente.</li><li>3. Coloque uma pequena quantidade de resina**; observe o aroma brevemente.</li><li>4. Extinguir com segurança; nunca deixar queimar incenso sozinho.</li></ol></section><section class=\"entry-section\"><h3>Armazenamento</h3><p>Resinas em frascos herméticos, frescos/secos.</p></section><section class=\"entry-section\"><h3>Precauções</h3><p><strong>A fumaça irrita os pulmões.</strong>Evite com asma, lactentes, preocupações de exposição à fumaça na gravidez ou alarmes de fumaça/risco de incêndio. Isto é<strong>não</strong>terapia antimicrobiana, libertação “protocolo”, ou um substituto para cuidados pastorais. O incenso bíblico tem história de adoração (por exemplo, incenso em Mateus 2:11 como dom; as leis do incenso do templo em Êxodo)—ensinar reverência e segurança juntos, não misticismo médico DIY.</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-olive-oil-anointing-pastoral-note-james-5"] = { title: "23. Oliva unção Pastoral Nota (Tiago 5)", html: "<section class=\"entry-section\"><h3>Propósito (educativo/pastoral)</h3><p>Azeite como prática de fé<strong>**de oração e cuidado em comunidades cristãs, seguindo o padrão pastoral de Tiago 5—</strong>não**um protocolo médico, farmacêutico, ou cura física garantida.</p></section><section class=\"entry-section\"><h3>Ingredientes</h3><ul><li>Uma pequena quantidade de azeite puro em um frasco limpo reservado para oração use</li></ul></section><section class=\"entry-section\"><h3>Passos pastorais (descrição educacional – não um mandato de liturgia)</h3><ol><li>1. Anciãos/pastores e a pessoa doente se reúnem em oração como a comunidade discerne.</li><li>2. Óleo pode ser aplicado levemente (ante cabeça ou cabeça)<strong>com consentimento</strong>, enquanto reza.</li><li>3. Procure cuidados médicos em paralelo – fé e medicina não são inimigos.</li><li>4. Mantenha o óleo limpo; não “prescreva” ervas sob o nome de unção.</li></ol></section><section class=\"entry-section\"><h3>Armazenamento</h3><p>Azeite fresco, fresco/escuro; substituir se rançoso.</p></section><section class=\"entry-section\"><h3>Precauções</h3><p>Isto é<strong>simbolismo sacramental/pastoral e oração</strong>, não uma reivindicação de tratamento. Não adie os cuidados de emergência. A alergia da pele ao azeite é incomum, mas possível. Não adicione óleos essenciais aleatórios à unção “supercarga” – que confunde categorias e pode prejudicar a pele.</p></section><section class=\"entry-section\"><h3>Nota de Escrita (honesta)</h3><p>“Está alguém entre vós doente? Chamem os anciãos da igreja a orar sobre eles e unjam-nos com óleo em nome do Senhor” (Tiago 5:14). A passagem centros<strong>oração e comunidade</strong>, não uma fórmula farmácia.</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-willow-bark-caution-prefer-clinician-otc-aspirin-literacy"] = { title: "24. Cuidado com as cascas de salgueiro — Prefere o clínico / OTC Aspirina Literacia", html: "<section class=\"entry-section\"><h3>Propósito (educativo)</h3><p>Ensinar porque este currículo<strong>não</strong>dá uma receita de dosagem de chá de salgueiro DIY para dor/febre.</p></section><section class=\"entry-section\"><h3>Por precaução em vez de uma receita</h3><ul><li>Willow bark (<em>Salix</em> spp.) contém compostos relacionados ao salicilato historicamente ligados à história da aspirina – mas a concentração de<strong>varia</strong>por espécie, colheita e preparação.</li><li>Aspirina e salicilatos têm toxicidade**clara, hemorragia, síndrome de Reye (crianças/adolescentes com doença viral), gravidez, úlcera e problemas de XXBX interação com fármacos.</li><li>Medindo chá de casca em casa é um substituto pobre para as formas de dose marcadas.</li></ul></section><section class=\"entry-section\"><h3>Prefere</h3><ul><li>Guia clínica para dor/febre.</li><li>Marcado OTC A aspirina<strong>apenas</strong>quando apropriado para a pessoa (idade, estado de gravidez, risco de hemorragia, doença viral na juventude, etc.) – leia rótulos; pergunte a um farmacêutico.</li><li>Medidas de conforto não medicamentosas (hidratação, repouso) quando adequado.</li></ul></section><section class=\"entry-section\"><h3>Não</h3><p>Ferver salgueiro de quintal aleatório para “aspirina natural”. Não dê experiências de salicilato a crianças. Não combinar chá de salgueiro com anticoagulantes casualmente.</p></section><section class=\"entry-section\"><h3>Nota de criação</h3><p>A história da medicina vegetal → inspira gratidão para ambos os jardins<strong>e</strong>farmácia cuidadosa – não nostalgia que ignora a segurança.</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-mustard-plaster-historical-education-burn-risk-discourage-diy"] = { title: "25. Educação Jack Mostarda (risco de queimadura — desencorajar DIY)", html: "<section class=\"entry-section\"><h3>Propósito (procurador/histórico)</h3><p>Explicar as chagas de mostarda como uma prática popular de XXBX XXBX – e porque este currículo XXBX desencoraja DIY**.</p></section><section class=\"entry-section\"><h3>Esboço histórico</h3><p>Semente de mostarda moída misturada com farinha/água foi aplicada externamente em manuais de amamentação mais antigos para criar calor/vermelhidão no peito ou nas costas. Queimaduras, bolhas e alterações pigmentares eram riscos conhecidos mesmo então.</p></section><section class=\"entry-section\"><h3>Por que desencorajar DIY</h3><ul><li>compostos pungentes de Mostarda pode<strong>quimicamente irritar e queimar</strong>pele - especialmente pele fina, crianças, idosos e pessoas com perda de sensação (por exemplo, algumas neuropatias diabetes).</li><li>Erros de tempo causam lesões.</li><li>As doenças respiratórias que necessitam de oxigênio, inaladores ou antibióticos não são resolvidas por uma queimadura torácica.</li></ul></section><section class=\"entry-section\"><h3>Se estudar apenas história</h3><p>Ler textos antigos como história; fazer**não</p></section><section class=\"entry-section\"><h3>recriar em uma pessoa. Prefere cuidados respiratórios clínicos modernos e calor seguro (meias quentes, ar umidificado por conselho clínico).\n\nPrecauções</h3><p>Não coloque preparações de mostarda em crianças. Não utilize se não sentir o calor normalmente. Procure cuidado para o sofrimento respiratório.</p></section>" };
window.RECIPE_LOCALES["pt"]["recipe-slippery-elm-inner-bark-gruel-tea-note-sustainability-first"] = { title: "26. Slippery Elm Inner-Bark Gruel / Tea Note (sustentabilidade-primeiro)", html: "<p>XX-09XXX Propósito (educativo/tradicional): XXBBXX Mucilaginous inner-bark gruel/tea aparece na tradição popular norte-americana para calmante garganta / folclore digestivo—ensinado aqui com XXBBX sustentabilidade primeiro XXBBXX .</p><section class=\"entry-section\"><h3>Ensino de sustentabilidade</h3><p>Populações selvagens de elm escorregadio (<em>Ulmus rubra</em>) enfrentaram doenças e pressão de colheita. Preferir:</p><ul><li>Compras de fornecedores de<strong>respeitáveis e sustentabilidade</strong>,<strong>ou</strong></li><li>Utilizando<strong>folha de marshmallow/raiz</strong>(<em>Althaea officinalis</em>) ou XXBX folha de banana**como alternativas mais suaves para mucilage folclore quando apropriado.</li></ul></section><section class=\"entry-section\"><h3>Se utilizar pó de olmo comercial escorregadio (nota de alimento adulto)</h3><ul><li>Mexa Cirque<strong>1⁄2–1 tsp</strong>em pó em um pouco de água fria para fazer uma pasta, em seguida, bata em<strong>6–8 oz</strong>água morna ou como um mingau fino; tomar lentamente.</li><li>Opcional: canela para sabor (alimento).</li></ul></section><section class=\"entry-section\"><h3>Armazenamento</h3><p>Seca/apertado; mistura fresco.</p></section><section class=\"entry-section\"><h3>Precauções</h3><p>Pode diminuir a absorção de medicamentos – separar de comprimidos por algumas horas por aconselhamento farmacêutico. Gravidez: pergunte ao médico. A textura pode desencadear engasgos — vá devagar. Não substitua a avaliação de sangramento GI, úlceras ou distúrbios da deglutição.</p></section>" };

(function () {
  var originals = Object.create(null);
  var captured = false;

  function captureEnFromDom() {
    if (captured) return;
    document.querySelectorAll("details.ref-entry").forEach(function (el) {
      var summary = el.querySelector(":scope > summary");
      var body = el.querySelector(":scope > .entry-body");
      if (!summary || !body) return;
      originals[el.id] = { title: summary.textContent, html: body.innerHTML };
    });
    captured = true;
  }

  window.bpApplyRecipeLocales = function bpApplyRecipeLocales() {
    var map = window.RECIPE_LOCALES;
    if (!map) return;
    captureEnFromDom();
    var lang = window.bpLang || "en";
    document.querySelectorAll("details.ref-entry").forEach(function (el) {
      var id = el.id;
      var summary = el.querySelector(":scope > summary");
      var body = el.querySelector(":scope > .entry-body");
      if (!summary || !body) return;
      var entry = null;
      if (lang === "en") {
        entry = (map.en && map.en[id]) || originals[id];
      } else if (map[lang]) {
        entry = map[lang][id];
      }
      if (!entry) return;
      summary.textContent = entry.title;
      body.innerHTML = entry.html;
    });
    document.querySelectorAll(".ref-toc a[href^='#']").forEach(function (a) {
      var id = a.getAttribute("href").slice(1);
      var entry = null;
      if (lang === "en") entry = (map.en && map.en[id]) || originals[id];
      else if (map[lang]) entry = map[lang][id];
      if (entry && entry.title) a.textContent = entry.title;
    });
  };

  var prev = window.bpApplyPageI18n;
  window.bpApplyPageI18n = function () {
    if (typeof prev === "function") prev();
    window.bpApplyRecipeLocales();
  };
})();
